import 'consejo.dart';

final List<Consejo> allConsejos = [
  const Consejo(category: 'Soledad', title: 'Superando la Soledad', description: 'La soledad puede ser un desierto emocional, pero Dios siempre está contigo. Él es tu compañero constante y te rodea con Su amor. Busca también la comunión con otros creyentes.', verse: 'Deuteronomio 31:6: \'Esforzaos y cobrad ánimo; no temáis, ni tengáis miedo de ellos, porque Jehová tu Dios es el que va contigo; no te dejará, ni te desamparará.\''),
  const Consejo(category: 'Duda', title: 'Fortaleciendo tu Fe contra la Duda', description: 'Es natural enfrentar dudas en tu caminar de fe. Entrégalas a Dios en oración y busca Su verdad en Su Palabra. La fe se fortalece al confiar en Él incluso cuando no entiendes.', verse: 'Marcos 9:24: \'E inmediatamente el padre del muchacho clamó y dijo: Creo; ayuda mi incredulidad.\''),
  const Consejo(category: 'Paciencia', title: 'Desarrollando Paciencia Divina', description: 'La paciencia es una virtud que se cultiva a través de las pruebas. Espera en el tiempo de Dios, sabiendo que Él obra todas las cosas para tu bien y Su propósito.', verse: 'Romanos 5:3-4: \'Y no solo esto, sino que también nos gloriamos en las tribulaciones, sabiendo que la tribulación produce paciencia; y la paciencia, prueba; y la prueba, esperanza.\''),
  const Consejo(category: 'Ira', title: 'Manejando la Ira de Forma Bíblica', description: 'La ira sin control puede ser destructiva. La Biblia nos enseña a ser lentos para la ira y a no dejar que el sol se ponga sobre nuestro enojo, buscando la reconciliación.', verse: 'Efesios 4:26: \'Airaos, pero no pequéis; no se ponga el sol sobre vuestro enojo.\''),
  const Consejo(category: 'Tentacion', title: 'Resistiendo la Tentación', description: 'La tentación es una realidad, pero Dios siempre proveerá una salida. Apóyate en Su fuerza, huye del mal y mantente firme en Su Palabra para superarla.', verse: '1 Corintios 10:13: \'No os ha sobrevenido ninguna tentación que no sea humana; pero fiel es Dios, que no os dejará ser tentados más de lo que podéis resistir, sino que dará también juntamente con la tentación la salida, para que podáis soportar.\''),
  const Consejo(category: 'Esperanza', title: 'Manteniendo la Esperanza en Tiempos Difíciles', description: 'La esperanza cristiana no es un deseo vano, sino una certeza basada en las promesas de Dios. Aunque la oscuridad te rodee, aférrate a la luz de Cristo, que nunca falla.', verse: 'Romanos 15:13: \'Y el Dios de esperanza os llene de todo gozo y paz en el creer, para que abundéis en esperanza por el poder del Espíritu Santo.\''),
  const Consejo(category: 'Gratitud', title: 'Cultivando un Corazón Agradecido', description: 'La gratitud transforma tu perspectiva y te conecta con la bondad de Dios. En cada circunstancia, buena o mala, encuentra algo por lo que dar gracias, reconociendo Su soberanía.', verse: '1 Tesalonicenses 5:18: \'Dad gracias en todo, porque esta es la voluntad de Dios para con vosotros en Cristo Jesús.\''),
  const Consejo(category: 'Sabiduria', title: 'Buscando Sabiduría Divina', description: 'Si te falta sabiduría para tomar decisiones, pídela a Dios con fe. Él la concede generosamente a quienes la buscan con un corazón sincero y humilde.', verse: 'Santiago 1:5: \'Y si alguno de vosotros tiene falta de sabiduría, pídala a Dios, el cual da a todos abundantemente y sin reproche, y le será dada.\''),
  const Consejo(category: 'Tristeza', title: 'Encontrando Consuelo en la Tristeza', description: 'Es válido sentir tristeza, pero no te quedes en ella. Dios es el Dios de toda consolación. Clama a Él en tu dolor y Él enjugará tus lágrimas y restaurará tu alma.', verse: '2 Corintios 1:3-4: \'Bendito sea el Dios y Padre de nuestro Señor Jesucristo, Padre de misericordias y Dios de toda consolación, el cual nos consuela en todas nuestras tribulaciones, para que podamos también nosotros consolar a los que están en cualquier tribulación, por medio de la consolación con que nosotros somos consolados por Dios.\''),
  const Consejo(category: 'Orgullo', title: 'Venciendo el Orgullo con Humildad', description: 'El orgullo precede a la caída. Vístete de humildad, reconociendo tu dependencia de Dios y sirviendo a los demás. La humildad trae gracia y exaltación de parte de Él.', verse: 'Santiago 4:6: \'Pero él da mayor gracia. Por esto dice: Dios resiste a los soberbios, y da gracia a los humildes.\''),
  const Consejo(category: 'Paz', title: 'Experimentando la Paz que Sobrepasa Todo Entendimiento', description: 'En medio del caos del mundo, la paz de Dios es un ancla para tu alma. No permitas que la preocupación te robe la paz. Confía tus ansiedades a Él y experimenta Su calma.', verse: 'Juan 14:27: \'La paz os dejo, mi paz os doy; yo no os la doy como el mundo la da. No se turbe vuestro corazón, ni tenga miedo.\''),
  const Consejo(category: 'Envidia', title: 'Superando la Envidia y la Comparación', description: 'La envidia roba la alegría y genera amargura. Celebra los éxitos de los demás como si fueran tuyos y concéntrate en el camino único que Dios tiene para ti.', verse: 'Gálatas 5:26: \'No nos hagamos vanagloriosos, irritándonos unos a otros, envidiándonos unos a otros.\''),
  const Consejo(category: 'Dolor', title: 'Encontrando Sanación en el Dolor', description: 'El dolor, ya sea físico o emocional, puede ser transformador. Dios usa incluso las experiencias más difíciles para moldearnos. Busca Su consuelo y Su propósito en medio del sufrimiento.', verse: 'Salmo 147:3: \'Él sana a los quebrantados de corazón, Y venda sus heridas.\''),
  const Consejo(category: 'Persecucion', title: 'Soportando la Persecución con Gozo', description: 'Ser perseguido por causa de Cristo es un honor. Mantén tu gozo en Él y recuerda que tu recompensa es grande en el cielo. Dios es tu defensor.', verse: 'Mateo 5:10-12: \'Bienaventurados los que padecen persecución por causa de la justicia, porque de ellos es el reino de los cielos. Bienaventurados sois cuando por mi causa os vituperen y os persigan, y digan toda clase de mal contra vosotros, mintiendo. Gozaos y alegraos, porque vuestro galardón es grande en los cielos; porque así persiguieron a los profetas que fueron antes de vosotros.\''),
  const Consejo(category: 'Disciplina', title: 'Aceptando la Disciplina Divina', description: 'La disciplina de Dios es una señal de Su amor. A través de ella, nos corrige y nos guía hacia la justicia. Acéptala con humildad y permite que te forme.', verse: 'Hebreos 12:6: \'Porque el Señor al que ama, disciplina, y azota a todo el que recibe por hijo.\''),
  const Consejo(category: 'Desanimo', title: 'Superando el Desánimo y la Frustración', description: 'El desánimo puede paralizar, pero no es el fin. Renueva tus fuerzas en el Señor, medita en Sus promesas y recuerda que Su Espíritu te capacita para seguir adelante.', verse: 'Isaías 40:31: \'Pero los que esperan a Jehová tendrán nuevas fuerzas; levantarán alas como las águilas; correrán, y no se cansarán; caminarán, y no se fatigarán.\''),
  const Consejo(category: 'Conviccion', title: 'La Importancia de la Convicción', description: 'Vive según tus convicciones bíblicas, incluso si te enfrentas a la oposición. Permite que el Espíritu Santo guíe tus decisiones y te dé el valor para defender la verdad.', verse: 'Romanos 14:5: \'Uno hace diferencia entre día y día; otro juzga iguales todos los días. Cada uno esté plenamente convencido en su propia mente.\''),
  const Consejo(category: 'Contentamiento', title: 'Hallando Contentamiento en Todas las Circunstancias', description: 'El contentamiento no depende de las circunstancias externas, sino de una profunda confianza en la provisión de Dios. Aprende a estar satisfecho en Cristo, sea mucho o poco lo que tengas.', verse: 'Filipenses 4:11-13: \'No lo digo porque tenga escasez, pues he aprendido a contentarme, cualquiera que sea mi situación; sé vivir humildemente, y sé tener abundancia; en todo y por todo estoy enseñado, así para estar saciado como para tener hambre, así para tener abundancia como para padecer necesidad. Todo lo puedo en Cristo que me fortalece.\''),
  const Consejo(category: 'Dependencia', title: 'Viviendo en Dependencia de Dios', description: 'Reconoce que sin Dios nada puedes hacer. Depende completamente de Él para tu fortaleza, dirección y provisión. Su poder se perfecciona en tu debilidad.', verse: 'Juan 15:5: \'Yo soy la vid, vosotros los pámpanos; el que permanece en mí, y yo en él, este lleva mucho fruto; porque separados de mí nada podéis hacer.\''),
  const Consejo(category: 'Generosidad', title: 'Practicando la Generosidad Bíblica', description: 'Dios ama al dador alegre. Sé generoso con tus recursos, tu tiempo y tus talentos, sabiendo que todo lo que tienes proviene de Él y Él te recompensará.', verse: '2 Corintios 9:7: \'Cada uno dé como propuso en su corazón: no con tristeza, ni por necesidad, porque Dios ama al dador alegre.\''),
  const Consejo(category: 'Integridad', title: 'Manteniendo la Integridad', description: 'Vive una vida de honestidad y rectitud, tanto en público como en privado. Tu integridad glorifica a Dios y es un testimonio poderoso de tu fe.', verse: 'Proverbios 11:3: \'La integridad de los rectos los encaminará; pero la perversidad de los prevaricadores los destruirá.\''),
  const Consejo(category: 'Justicia', title: 'Buscando la Justicia de Dios', description: 'Procura vivir en justicia, buscando lo que es correcto y honrando a Dios en todas tus acciones. Él es el Juez justo y vindicará a los suyos.', verse: 'Miqueas 6:8: \'Oh hombre, él te ha declarado lo que es bueno, y qué pide Jehová de ti: solamente hacer justicia, y amar misericordia, y humillarte ante tu Dios.\''),
  const Consejo(category: 'Oracion', title: 'El Poder Transformador de la Oración', description: 'La oración es tu línea directa con Dios. Ora sin cesar, presenta tus peticiones con fe y espera en Su respuesta. Él te escucha y tiene planes perfectos.', verse: 'Filipenses 4:6-7: \'Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias. Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.\''),
  const Consejo(category: 'Obediencia', title: 'La Bendición de la Obediencia', description: 'La obediencia a la Palabra de Dios no es una carga, sino un camino hacia la bendición y una vida plena. Confía en Sus mandamientos, porque son para tu bien.', verse: 'Juan 14:15: \'Si me amáis, guardad mis mandamientos.\''),
  const Consejo(category: 'Aceptacion', title: 'Aceptando el Plan de Dios', description: 'A veces las cosas no salen como esperamos. Aprende a aceptar la voluntad de Dios para tu vida, confiando que Sus caminos son más altos que los tuyos y siempre buenos.', verse: 'Proverbios 3:5-6: \'Fíate de Jehová de todo tu corazón, y no te apoyes en tu propia prudencia. Reconócelo en todos tus caminos, y él enderezará tus veredas.\''),
  const Consejo(category: 'Adversidad', title: 'Navegando la Adversidad con Fortaleza', description: 'La adversidad es inevitable, pero tu reacción a ella define tu carácter. Permite que las pruebas te fortalezcan en lugar de debilitarte, confiando en que Dios está contigo.', verse: 'Santiago 1:2-4: \'Hermanos míos, tened por sumo gozo cuando os halléis en diversas pruebas, sabiendo que la prueba de vuestra fe produce paciencia. Mas tenga la paciencia su obra completa, para que seáis perfectos y cabales, sin que os falte cosa alguna.\''),
  const Consejo(category: 'Consuelo', title: 'Encontrando Consuelo en Cristo', description: 'Cuando el mundo te falle, Cristo es tu consuelo inagotable. Él entiende tu dolor y te ofrece paz y esperanza en medio de la aflicción. Refúgiate en Él.', verse: 'Salmo 23:4: \'Aunque ande en valle de sombra de muerte, No temeré mal alguno, porque tú estarás conmigo; Tu vara y tu cayado me infundirán aliento.\''),
  const Consejo(category: 'Santidad', title: 'Buscando la Santidad en tu Vida', description: 'La santidad no es perfección instantánea, sino un proceso de ser apartado para Dios. Esfuérzate por vivir una vida que le agrada, con la ayuda del Espíritu Santo.', verse: '1 Pedro 1:15-16: \'Sino, como aquel que os llamó es santo, sed también vosotros santos en toda vuestra manera de vivir; porque escrito está: Sed santos, porque yo soy santo.\''),
  const Consejo(category: 'Liderazgo', title: 'Principios Bíblicos para el Liderazgo', description: 'Si eres un líder, busca servir con humildad y justicia. Lidera con integridad, amor y un corazón de siervo, imitando a Cristo, el gran Pastor.', verse: 'Marcos 10:43-45: \'Pero no será así entre vosotros, sino que el que quiera hacerse grande entre vosotros será vuestro servidor, y el que de vosotros quiera ser el primero, será siervo de todos. Porque el Hijo del Hombre no vino para ser servido, sino para servir, y para dar su vida en rescate por muchos.\''),
  const Consejo(category: 'Identidad', title: 'Afirmando tu Identidad en Cristo', description: 'Tu verdadero valor no está en lo que haces o tienes, sino en quién eres en Cristo. Eres amado, escogido y redimido. Aférrate a esta verdad y no busques validación en el mundo.', verse: '2 Corintios 5:17: \'De modo que si alguno está en Cristo, nueva criatura es; las cosas viejas pasaron; he aquí todas son hechas nuevas.\''),
  const Consejo(category: 'Promesas', title: 'Confiando en las Promesas de Dios', description: 'Las promesas de Dios son fieles y verdaderas. Apóyate en ellas en cada situación, sabiendo que Él cumple Su Palabra. Su fidelidad es tu garantía.', verse: '2 Pedro 1:4: \'por medio de las cuales nos ha dado preciosas y grandísimas promesas, para que por ellas llegaseis a ser participantes de la naturaleza divina, habiendo huido de la corrupción que hay en el mundo a causa de la concupiscencia.\''),
  const Consejo(category: 'Matrimonio', title: 'Fortaleciendo tu Matrimonio', description: 'El matrimonio es un pacto sagrado. Cultívalo con amor, respeto, comunicación y perdón. Pongan a Cristo en el centro de su unión.', verse: 'Efesios 5:25: \'Maridos, amad a vuestras mujeres, así como Cristo amó a la iglesia, y se entregó a sí mismo por ella.\''),
  const Consejo(category: 'Crianza', title: 'Crianza de Hijos con Sabiduría Bíblica', description: 'Educa a tus hijos en el temor del Señor, con amor, disciplina y ejemplo. Enséñales Sus caminos desde pequeños para que no se aparten de ellos.', verse: 'Proverbios 22:6: \'Instruye al niño en su camino, Y aun cuando fuere viejo no se apartará de él.\''),
  const Consejo(category: 'Trabajo', title: 'Excelencia en el Trabajo y Servicio', description: 'Haz todo lo que hagas con excelencia, como para el Señor y no para los hombres. Honra a Dios en tu labor diaria, sea cual sea, y Él te bendecirá.', verse: 'Colosenses 3:23-24: \'Y todo lo que hagáis, hacedlo de corazón, como para el Señor y no para los hombres; sabiendo que del Señor recibiréis la recompensa de la herencia, porque a Cristo el Señor servís.\''),
  const Consejo(category: 'Salvacion', title: 'El Regalo de la Salvación', description: 'La salvación es un don gratuito de Dios por medio de la fe en Jesucristo. Acepta Su sacrificio, arrepiéntete de tus pecados y recibe la vida eterna que Él ofrece.', verse: 'Romanos 10:9-10: \'que si confesares con tu boca que Jesús es el Señor, y creyeres en tu corazón que Dios le levantó de los muertos, serás salvo. Porque con el corazón se cree para justicia, pero con la boca se confiesa para salvación.\''),
  const Consejo(category: 'Evangelismo', title: 'Compartiendo tu Fe (Evangelismo)', description: 'No te avergüences del evangelio. Comparte las buenas nuevas de Cristo con amor y valentía, siendo testigo de Su poder transformador en tu vida.', verse: 'Romanos 1:16: \'Porque no me avergüenzo del evangelio, porque es poder de Dios para salvación a todo aquel que cree; al judío primeramente, y también al griego.\''),
  const Consejo(category: 'Afliccion', title: 'Encontrando Gozo en la Aflicción', description: 'Aunque parezca contradictorio, Dios puede darte gozo en medio de la aflicción. Conoce que tus pruebas producen perseverancia y perfeccionan tu carácter en Él.', verse: 'Romanos 5:3-5: \'Y no solo esto, sino que también nos gloriamos en las tribulaciones, sabiendo que la tribulación produce paciencia; y la paciencia, prueba; y la prueba, esperanza; y la esperanza no avergüenza; porque el amor de Dios ha sido derramado en nuestros corazones por el Espíritu Santo que nos fue dado.\''),
  const Consejo(category: 'Sanidad', title: 'Clamando por Sanidad Divina', description: 'Dios es el Gran Sanador. Presenta tus enfermedades y dolencias delante de Él con fe, y confía en Su poder y Su voluntad perfecta para sanarte.', verse: 'Jeremías 17:14: \'Sáname, oh Jehová, y seré sano; sálvame, y seré salvo; porque tú eres mi alabanza.\''),
  const Consejo(category: 'Muerte', title: 'Esperanza Frente a la Muerte', description: 'Para el creyente, la muerte no es el final, sino el paso a la vida eterna con Cristo. Consuélate en esta verdad y comparte esta esperanza con quienes sufren la pérdida.', verse: 'Juan 11:25-26: \'Le dijo Jesús: Yo soy la resurrección y la vida; el que cree en mí, aunque esté muerto, vivirá. Y todo aquel que vive y cree en mí, no morirá eternamente. ¿Crees esto?\''),
  const Consejo(category: 'DepresiÃ³n', title: 'Buscando Ayuda en la Depresión', description: 'La depresión es una carga pesada. No la enfrentes solo. Busca ayuda profesional si es necesario y confía en que Dios está contigo, aun en los valles más profundos. Él te levantará.', verse: 'Salmo 42:11: \'¿Por qué te abates, oh alma mía, Y por qué te turbas dentro de mí? Espera en Dios; porque aún he de alabarle, Salvación mía y Dios mío.\''),
  const Consejo(category: 'Guerra Espiritual', title: 'Batallando en la Guerra Espiritual', description: 'Estás en una guerra espiritual. Vístete de toda la armadura de Dios, ora sin cesar y resiste al diablo. No luchas solo; Cristo ya ha vencido.', verse: 'Efesios 6:11-12: \'Vestíos de toda la armadura de Dios, para que podáis estar firmes contra las asechanzas del diablo. Porque no tenemos lucha contra sangre y carne, sino contra principados, contra potestades, contra los gobernadores de las tinieblas de este siglo, contra huestes espirituales de maldad en las regiones celestes.\''),
  const Consejo(category: 'Adicciones', title: 'Libertad de Adicciones', description: 'Las adicciones esclavizan, pero Cristo ofrece verdadera libertad. Clama a Él por fortaleza, busca apoyo en Su comunidad y permite que Su poder te rescate de toda atadura.', verse: 'Juan 8:36: \'Así que, si el Hijo os libertare, seréis verdaderamente libres.\''),
  const Consejo(category: 'Temor del Hombre', title: 'Venciendo el Temor del Hombre', description: 'No temas lo que los hombres puedan hacerte. Temer a Dios es el principio de la sabiduría y te libera del temor a la opinión o el rechazo de los demás.', verse: 'Proverbios 29:25: \'El temor del hombre pondrá lazo; Mas el que confía en Jehová será librado.\''),
  const Consejo(category: 'Mentira', title: 'Hablando la Verdad en Amor', description: 'La verdad es fundamental en la vida del creyente. Habla la verdad siempre, pero hazlo con amor y gracia. Sé un reflejo de Cristo, quien es la Verdad.', verse: 'Efesios 4:15: \'Sino que, siguiendo la verdad en amor, crezcamos en todo en aquel que es la cabeza, esto es, Cristo.\''),
  const Consejo(category: 'Desempleo', title: 'Confiando en Dios en el Desempleo', description: 'El desempleo puede generar preocupación, pero Dios es tu proveedor. Confía en Él para abrir nuevas puertas y suplir todas tus necesidades según Sus riquezas en gloria.', verse: 'Filipenses 4:19: \'Mi Dios, pues, suplirá todo lo que os falta conforme a sus riquezas en gloria en Cristo Jesús.\''),
  const Consejo(category: 'Abuso', title: 'Sanación del Abuso', description: 'El abuso deja heridas profundas. Dios es tu refugio y protector. Busca ayuda, clama a Él por sanidad y justicia. Él ve tu dolor y te consuela.', verse: 'Salmo 55:22: \'Echa sobre Jehová tu carga, y él te sustentará; No dejará para siempre caído al justo.\''),
  const Consejo(category: 'Divorcio', title: 'Navegando el Divorcio con Gracia', description: 'El divorcio es doloroso, pero no es el fin de tu historia con Dios. Él te ofrece gracia, sanidad y un nuevo comienzo. Confía en Su plan para restaurarte.', verse: 'Isaías 43:18-19: \'No os acordéis de las cosas pasadas, ni consideréis las cosas antiguas. He aquí que yo hago cosa nueva; pronto saldrá a luz; ¿no la conoceréis? Otra vez abriré camino en el desierto, y ríos en la soledad.\''),
  const Consejo(category: 'Perdida de un Hijo', title: 'Consuelo en la Pérdida de un Hijo', description: 'La pérdida de un hijo es un dolor inmenso. Dios te abraza en tu luto. Él es el Dios de todo consuelo y te sostendrá en tu dolor, dándote paz que sobrepasa el entendimiento.', verse: 'Salmo 34:18: \'Cercano está Jehová a los quebrantados de corazón; Y salva a los contritos de espíritu.\''),
  const Consejo(category: 'Rechazo', title: 'Superando el Rechazo', description: 'El rechazo duele, pero tu valor no lo define la opinión de los demás, sino el amor incondicional de Dios por ti. Él te acepta completamente en Cristo.', verse: 'Salmo 27:10: \'Aunque mi padre y mi madre me dejaran, Con todo, Jehová me recogerá.\''),
  const Consejo(category: 'Duelo', title: 'Procesando el Duelo Bíblicamente', description: 'El duelo es un proceso natural. Date permiso para llorar y busca el consuelo de Dios y de tu comunidad. Él es fiel para sanar tu corazón roto con el tiempo.', verse: 'Mateo 5:4: \'Bienaventurados los que lloran, porque ellos recibirán consolación.\''),
  const Consejo(category: 'Amargura', title: 'Liberándote de la Amargura', description: 'La amargura envenena el alma. Elige perdonar, aun cuando sea difícil, y permite que Dios quite esa raíz de amargura de tu corazón, reemplazándola con Su paz.', verse: 'Hebreos 12:15: \'Mirad bien, no sea que alguno deje de alcanzar la gracia de Dios; que brotando alguna raíz de amargura, os estorbe, y por ella muchos sean contaminados;\''),
  const Consejo(category: 'Inseguridad', title: 'Superando la Inseguridad', description: 'Tu confianza no debe basarse en tus habilidades, sino en el poder de Dios en ti. Él te ha dado dones y talentos; úsalos con seguridad, sabiendo que Él te capacita.', verse: '2 Timoteo 1:7: \'Porque no nos ha dado Dios espíritu de cobardía, sino de poder, de amor y de dominio propio.\''),
  const Consejo(category: 'Pereza', title: 'Venciendo la Pereza', description: 'La pereza impide el progreso. Sé diligente en tus responsabilidades, trabaja con esfuerzo y disciplina, y confía en que tu trabajo hecho para el Señor no es en vano.', verse: 'Proverbios 6:6: \'Ve a la hormiga, oh perezoso, mira sus caminos, y sé sabio;\''),
  const Consejo(category: 'Chisme', title: 'Evitando el Chisme y la Calumnia', description: 'Las palabras tienen poder. Evita el chisme y la calumnia, que destruyen relaciones y reputaciones. Edifica a los demás con tus palabras y sé un portador de paz.', verse: 'Proverbios 16:28: \'El hombre perverso levanta contienda, Y el chismoso aparta a los mejores amigos.\''),
  const Consejo(category: 'Crítica', title: 'Manejando la Crítica Constructivamente', description: 'La crítica puede ser difícil, pero considérala una oportunidad para crecer. Discierne si es justa, y si lo es, aprende de ella. Si no, deséchala con sabiduría.', verse: 'Proverbios 12:1: \'El que ama la instrucción ama la sabiduría; Mas el que aborrece la reprensión es ignorante.\''),
  const Consejo(category: 'Abundancia', title: 'Mayordomía en la Abundancia', description: 'Cuando Dios te bendice con abundancia, sé un buen mayordomo. Administra tus recursos con sabiduría, generosidad y en obediencia a Su voluntad.', verse: '1 Timoteo 6:17-19: \'A los ricos de este siglo manda que no sean altivos, ni pongan la esperanza en las riquezas, las cuales son inciertas, sino en el Dios vivo, que nos da todas las cosas en abundancia para que las disfrutemos. Que hagan bien, que sean ricos en buenas obras, dadivosos, generosos; atesorando para sí buen fundamento para lo por venir, para que echen mano de la vida eterna.\''),
  const Consejo(category: 'Pobreza', title: 'Confiando en Dios en la Pobreza', description: 'La pobreza no es una marca de desfavor. Dios se preocupa por el pobre y es tu proveedor. Confía en que Él suplirá tus necesidades y te dará fortaleza para perseverar.', verse: 'Proverbios 28:27: \'El que da al pobre no tendrá pobreza; Mas el que aparta sus ojos tendrá muchas maldiciones.\''),
  const Consejo(category: 'Salud', title: 'Cuidando tu Salud Holísticamente', description: 'Tu cuerpo es templo del Espíritu Santo. Cuida tu salud física, mental y espiritual. Honra a Dios con tus hábitos y busca Su dirección en tu bienestar.', verse: '1 Corintios 6:19-20: \'¿O ignoráis que vuestro cuerpo es templo del Espíritu Santo, el cual está en vosotros, el cual tenéis de Dios, y que no sois vuestros? Porque habéis sido comprados por precio; glorificad, pues, a Dios en vuestro cuerpo y en vuestro espíritu, los cuales son de Dios.\''),
  const Consejo(category: 'Mente', title: 'Renovando tu Mente', description: 'Tus pensamientos tienen un gran poder. Renueva tu mente con la Palabra de Dios, desechando todo lo que no glorifica a Él y llenándola de lo verdadero, lo puro y lo noble.', verse: 'Romanos 12:2: \'No os conforméis a este siglo, sino transformaos por medio de la renovación de vuestro entendimiento, para que comprobéis cuál sea la buena voluntad de Dios, agradable y perfecta.\''),
  const Consejo(category: 'Amor', title: 'La Esencia del Amor Cristiano', description: 'Ama a Dios sobre todas las cosas y a tu prójimo como a ti mismo. El amor es el mayor de los mandamientos y la marca distintiva del seguidor de Cristo.', verse: '1 Juan 4:7-8: \'Amados, amémonos unos a otros; porque el amor es de Dios. Todo aquel que ama, es nacido de Dios, y conoce a Dios. El que no ama, no ha conocido a Dios; porque Dios es amor.\''),
  const Consejo(category: 'Esperar en Dios', title: 'Esperar el Tiempo de Dios', description: 'Aprender a esperar en el Señor es una lección de fe. Su tiempo es perfecto, aunque no coincida con el tuyo. Permanece en oración y confía en que Él actuará a Su debido tiempo.', verse: 'Salmo 27:14: \'Espera a Jehová; Esfuérzate, y aliéntese tu corazón; Sí, espera a Jehová.\''),
  const Consejo(category: 'Confianza', title: 'Edificando una Confianza Inquebrantable', description: 'La confianza en Dios es el fundamento de una vida plena. Pon toda tu esperanza y fe en Él, y Él te guiará y sostendrá en cada paso del camino.', verse: 'Proverbios 3:5-6: \'Fíate de Jehová de todo tu corazón, y no te apoyes en tu propia prudencia. Reconócelo en todos tus caminos, y él enderezará tus veredas.\''),
  const Consejo(category: 'Pasion', title: 'Reavivando tu Pasión por Cristo', description: 'No dejes que el primer amor se enfríe. Busca a Dios con fervor, lee Su Palabra y ora. Reaviva tu pasión por Él y Su propósito en tu vida.', verse: 'Apocalipsis 2:4: \'Pero tengo contra ti, que has dejado tu primer amor.\''),
  const Consejo(category: 'Disciplina', title: 'La Importancia de la Disciplina Espiritual', description: 'La disciplina espiritual, como la lectura bíblica y la oración, te acerca a Dios. Dedica tiempo intencional a crecer en tu relación con Él.', verse: '1 Timoteo 4:7-8: \'Desecha las fábulas profanas y de viejas. Ejercítate para la piedad; porque el ejercicio corporal para poco es provechoso, pero la piedad para todo aprovecha, pues tiene promesa de esta vida presente, y de la venidera.\''),
  const Consejo(category: 'Compasion', title: 'Desarrollando un Corazón Compasivo', description: 'Sigue el ejemplo de Jesús y muestra compasión a los que sufren. Extiende ayuda, amor y misericordia a quienes te rodean, reflejando el corazón de Dios.', verse: 'Colosenses 3:12: \'Vestíos, pues, como escogidos de Dios, santos y amados, de entrañable misericordia, de benignidad, de humildad, de mansedumbre, de paciencia;\''),
  const Consejo(category: 'Paz Mental', title: 'Encontrando Paz Mental', description: 'La agitación mental es común, pero la paz de Dios está disponible. Concéntrate en Cristo, ora por tus preocupaciones y deja que Su paz guarde tu mente y corazón.', verse: 'Filipenses 4:7: \'Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.\''),
  const Consejo(category: 'Arrepentimiento', title: 'El Verdadero Arrepentimiento', description: 'El arrepentimiento no es solo sentir remordimiento, sino un cambio de mente y corazón que te lleva a alejarte del pecado y volverte a Dios. Él te perdona y te restaura.', verse: 'Hechos 3:19: \'Así que, arrepentíos y convertíos, para que vuestros pecados sean borrados; para que vengan de la presencia del Señor tiempos de refrigerio.\''),
  const Consejo(category: 'Dones', title: 'Descubriendo y Usando tus Dones Espirituales', description: 'Dios te ha dotado con dones espirituales. Descúbrelos, desarróllalos y úsalos para edificar la iglesia y servir a los demás. Cada don es vital en el cuerpo de Cristo.', verse: '1 Pedro 4:10: \'Cada uno según el don que ha recibido, minístrelo a los otros, como buenos administradores de la multiforme gracia de Dios.\''),
  const Consejo(category: 'Gratitud', title: 'Viviendo una Vida de Gratitud', description: 'No esperes a tenerlo todo para ser agradecido. La gratitud es una elección que trae gozo y te ayuda a ver la bondad de Dios en cada detalle de tu vida. Practícala a diario.', verse: 'Salmo 107:1: \'Dad gracias a Jehová, porque él es bueno; Porque para siempre es su misericordia.\''),
  const Consejo(category: 'Humildad', title: 'La Fortaleza de la Humildad', description: 'La humildad no es debilidad, sino una gran fortaleza. Reconoce tu dependencia de Dios y sométete a Su voluntad. Él exalta a los humildes a Su debido tiempo.', verse: '1 Pedro 5:5-6: \'Igualmente, jóvenes, estad sujetos a los ancianos; y todos, sumisos unos a otros, revestíos de humildad; porque: Dios resiste a los soberbios, y da gracia a los humildes. Humillaos, pues, bajo la poderosa mano de Dios, para que él os exalte cuando fuere tiempo;\''),
  const Consejo(category: 'Fidelidad', title: 'La Fidelidad de Dios y Nuestra Respuesta', description: 'Dios es fiel en todo tiempo, incluso cuando nosotros no lo somos. Responde a Su fidelidad siendo fiel en tus compromisos, tu fe y tu servicio a Él.', verse: 'Lamentaciones 3:22-23: \'Por la misericordia de Jehová no hemos sido consumidos, porque nunca decayeron sus misericordias. Nuevas son cada mañana; grande es tu fidelidad.\''),
  const Consejo(category: 'Esperanza Eterna', title: 'La Esperanza de la Vida Eterna', description: 'Nuestra esperanza no termina con esta vida, sino que se extiende a la eternidad con Cristo. Vive con esta perspectiva, sabiendo que lo mejor está por venir.', verse: 'Tito 2:13: \'aguardando la esperanza bienaventurada y la manifestación gloriosa de nuestro gran Dios y Salvador Jesucristo,\''),
  const Consejo(category: 'Sabiduria', title: 'Discernimiento y Sabiduría', description: 'El discernimiento es clave para navegar la vida. Pide a Dios que te dé sabiduría para distinguir entre el bien y el mal, y para tomar decisiones que le honren.', verse: 'Hebreos 5:14: \'pero el alimento sólido es para los que han alcanzado madurez, para los que por el uso tienen los sentidos ejercitados en el discernimiento del bien y del mal.\''),
  const Consejo(category: 'Amistad', title: 'Cultivando Amistades Piadosas', description: 'Elige amigos que te animen en tu fe y te ayuden a crecer. Las buenas amistades son un regalo de Dios que te fortalecen en tu caminar.', verse: 'Proverbios 27:17: \'Hierro con hierro se aguza; Y así el hombre aguza el rostro de su amigo.\''),
  const Consejo(category: 'DepresiÃ³n', title: 'La Luz de Cristo en la Depresión', description: 'En los momentos más oscuros de la depresión, la luz de Cristo brilla más intensamente. Aférrate a Su presencia, Él es tu refugio y tu fortaleza inquebrantable.', verse: 'Salmo 23:4: \'Aunque ande en valle de sombra de muerte, No temeré mal alguno, porque tú estarás conmigo; Tu vara y tu cayado me infundirán aliento.\''),
  const Consejo(category: 'Ansiedad', title: 'La Paz de Dios ante la Ansiedad', description: 'Cuando la ansiedad te oprima, entrega cada preocupación a Dios en oración. Su paz, que excede todo entendimiento, guardará tu corazón y tus pensamientos en Cristo Jesús.', verse: 'Filipenses 4:6-7: \'Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias. Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.\''),
  const Consejo(category: 'PerdÃ³n', title: 'El Regalo Liberador del Perdón', description: 'Perdonar no es un sentimiento, sino una decisión que te libera del resentimiento. Al igual que Cristo te perdonó, perdona a quienes te han ofendido y experimenta Su paz.', verse: 'Colosenses 3:13: \'soportándoos unos a otros, y perdonándoos unos a otros si alguno tuviere queja contra otro. De la manera que Cristo os perdonó, así también hacedlo vosotros.\''),
  const Consejo(category: 'Fe', title: 'Creciendo en Fe', description: 'Tu fe es un viaje, no un destino. Aliméntala con la Palabra de Dios, confiando en Sus promesas y actuando en obediencia. Cada paso de fe te fortalece.', verse: 'Romanos 10:17: \'Así que la fe es por el oír, y el oír, por la palabra de Dios.\''),
  const Consejo(category: 'Relaciones', title: 'Sanando Relaciones Rotas', description: 'Las relaciones son complejas, pero con la guía de Dios pueden ser sanadas. Busca la reconciliación, perdona y ama como Cristo te ama. Él es el Restaurador de relaciones.', verse: 'Romanos 12:18: \'Si es posible, en cuanto dependa de vosotros, tened paz con todos los hombres.\''),
  const Consejo(category: 'Finanzas', title: 'Manejo de Finanzas con Sabiduría', description: 'Dios es el dueño de todo. Administra tus finanzas con sabiduría, buscando Su reino primero, siendo generoso y evitando la deuda. Él proveerá todas tus necesidades.', verse: 'Mateo 6:33: \'Mas buscad primeramente el reino de Dios y su justicia, y todas estas cosas os serán añadidas.\''),
  const Consejo(category: 'Enfermedad', title: 'Enfrentando la Enfermedad con Fe', description: 'La enfermedad puede ser un gran desafío, pero Dios es tu sanador y tu fuerza. Clama a Él en oración, busca la unción de los ancianos y confía en Su soberanía y amor.', verse: 'Santiago 5:14-15: \'¿Está alguno entre vosotros afligido? Haga oración. ¿Está alguno alegre? Cante alabanzas. ¿Está alguno enfermo entre vosotros? Llame a los ancianos de la iglesia, y oren por él, ungiéndole con aceite en el nombre del Señor. Y la oración de fe salvará al enfermo, y el Señor lo levantará; y si hubiere cometido pecados, le serán perdonados.\''),
  const Consejo(category: 'Paz Interior', title: 'Cultivando la Paz Interior', description: 'La verdadera paz no se encuentra en la ausencia de problemas, sino en la presencia de Cristo en tu corazón. Rinde tus preocupaciones a Él y permite que Su paz reine en tu interior.', verse: 'Juan 16:33: \'Estas cosas os he hablado para que en mí tengáis paz. En el mundo tendréis aflicción; pero confiad, yo he vencido al mundo.\''),
  const Consejo(category: 'Temor', title: 'Libertad del Temor', description: 'El temor es un enemigo de la fe. Recuerda que Dios no te ha dado espíritu de cobardía, sino de poder, amor y dominio propio. Clama a Él y Él te librará de todos tus temores.', verse: 'Salmo 34:4: \'Busqué a Jehová, y él me oyó, Y me libró de todos mis temores.\''),
  const Consejo(category: 'Propósito', title: 'Descubriendo tu Propósito en Dios', description: 'Fuiste creado con un propósito divino. Busca a Dios en oración y en Su Palabra para descubrir el plan único que Él tiene para tu vida y vive para Su gloria.', verse: 'Romanos 8:28: \'Y sabemos que a los que aman a Dios, todas las cosas les ayudan a bien, esto es, a los que conforme a su propósito son llamados.\''),
  const Consejo(category: 'Crecimiento Espiritual', title: 'Claves para el Crecimiento Espiritual', description: 'El crecimiento espiritual es un proceso continuo. Aliméntate de la Palabra, ora sin cesar, busca la comunión con creyentes y obedece al Espíritu Santo. Sé diligente en tu fe.', verse: '2 Pedro 3:18: \'Antes bien, creced en la gracia y el conocimiento de nuestro Señor y Salvador Jesucristo. A él sea gloria ahora y hasta el día de la eternidad. Amén.\''),
  const Consejo(category: 'Dolor', title: 'El Dolor como Catalizador', description: 'El dolor puede ser un catalizador para un mayor crecimiento. Permite que Dios use tus sufrimientos para refinarte y acercarte más a Él. Encuentra significado en medio de la adversidad.', verse: 'Romanos 8:18: \'Pues tengo por cierto que las aflicciones del tiempo presente no son comparables con la gloria venidera que en nosotros ha de manifestarse.\''),
  const Consejo(category: 'Tentacion', title: 'Previniendo la Tentación', description: 'Sé consciente de tus debilidades y ora para no caer en tentación. Huye del mal, llena tu mente con la Palabra de Dios y busca la compañía de quienes te edifican.', verse: 'Mateo 26:41: \'Velad y orad, para que no entréis en tentación; el espíritu a la verdad está dispuesto, pero la carne es débil.\''),
  const Consejo(category: 'PerdÃ³n', title: 'El Perdón de Dios', description: 'El perdón de Dios es completo y restaurador. Si has pecado, arrepiéntete y confiesa tus faltas. Él es fiel y justo para perdonarte y limpiarte de toda maldad.', verse: '1 Juan 1:9: \'Si confesamos nuestros pecados, él es fiel y justo para perdonar nuestros pecados, y limpiarnos de toda maldad.\''),
  const Consejo(category: 'Estres', title: 'Manejando el Estrés con Fe', description: 'El estrés es una realidad en la vida moderna. Aprende a confiar tus cargas a Dios. Descansa en Su soberanía y busca momentos de calma y quietud en Su presencia.', verse: 'Salmo 55:22: \'Echa sobre Jehová tu carga, y él te sustentará; No dejará para siempre caído al justo.\''),
  const Consejo(category: 'Dudas', title: 'Cuando las Dudas Atacan tu Fe', description: 'Las dudas son parte del viaje de fe. No las suprimas; preséntalas a Dios en oración. Busca respuestas en Su Palabra y en la comunidad de creyentes. Él es más grande que tus dudas.', verse: 'Santiago 1:6: \'Pero pida con fe, no dudando nada; porque el que duda es semejante a la onda del mar, que es arrastrada por el viento y echada de una parte a otra.\''),
  const Consejo(category: 'Paciencia', title: 'La Paciencia de un Sembrador', description: 'Así como el agricultor espera pacientemente la cosecha, aprende a esperar en Dios. Tu perseverancia en las pruebas produce carácter y te acerca a la recompensa.', verse: 'Santiago 5:7: \'Por tanto, hermanos, tened paciencia hasta la venida del Señor. Mirad cómo el labrador espera el precioso fruto de la tierra, aguardando con paciencia hasta que reciba la lluvia temprana y la tardía.\''),
  const Consejo(category: 'Desesperacion', title: 'Hallando Esperanza en la Desesperación', description: 'Cuando te sientas desesperado, recuerda que Dios es el Dios de la esperanza. Clama a Él, medita en Sus promesas y espera en Su rescate. Él nunca te abandonará.', verse: 'Romanos 15:13: \'Y el Dios de esperanza os llene de todo gozo y paz en el creer, para que abundéis en esperanza por el poder del Espíritu Santo.\''),
  const Consejo(category: 'Soledad', title: 'La Presencia Constante de Dios', description: 'Nunca estás verdaderamente solo, porque Dios está siempre contigo. Su presencia te envuelve y te consuela en cada momento de soledad. Búscale en quietud.', verse: 'Salmo 139:7-10: \'¿A dónde me iré de tu Espíritu? ¿Y a dónde huiré de tu presencia? Si subiere a los cielos, allí estás tú; Y si en el Seol hiciere mi estrado, he aquí, allí tú estás. Si tomare las alas del alba Y habitare en el extremo del mar, Aun allí me guiará tu mano, Y me asirá tu diestra.\''),
  const Consejo(category: 'PerdÃ³n', title: 'Perdonándote a Ti Mismo', description: 'Así como Dios te ha perdonado, aprende a perdonarte a ti mismo por tus errores. No te castigues con culpa y vergüenza. Acepta la gracia de Dios y avanza en libertad.', verse: 'Filipenses 3:13-14: \'Hermanos, yo mismo no pretendo haberlo ya alcanzado; pero una cosa hago: olvidando ciertamente lo que queda atrás, y extendiéndome a lo que está delante, prosigo a la meta, al premio del supremo llamamiento de Dios en Cristo Jesús.\''),
  const Consejo(category: 'Amor Incondicional', title: 'El Poder del Amor Incondicional', description: 'Dios te ama con un amor incondicional. Refleja ese amor a los demás, incluso a aquellos que son difíciles de amar. El amor verdadero transforma.', verse: 'Romanos 5:8: \'Mas Dios muestra su amor para con nosotros, en que siendo aún pecadores, Cristo murió por nosotros.\''),
  const Consejo(category: 'Conflictos', title: 'Resolviendo Conflictos de Manera Bíblica', description: 'Los conflictos son parte de la vida, pero puedes resolverlos con sabiduría. Busca la paz, la reconciliación y el entendimiento, siguiendo los principios de Cristo.', verse: 'Mateo 5:9: \'Bienaventurados los pacificadores, porque ellos serán llamados hijos de Dios.\''),
  const Consejo(category: 'Adoracion', title: 'La Belleza de la Adoración', description: 'La adoración es más que cantar; es un estilo de vida de honrar a Dios en todo lo que haces. Adórale en espíritu y en verdad, con todo tu corazón y tu mente.', verse: 'Juan 4:24: \'Dios es Espíritu; y los que le adoran, en espíritu y en verdad es necesario que adoren.\''),
  const Consejo(category: 'Paz', title: 'La Paz en la Tormenta', description: 'Cuando la vida se siente como una tormenta, la paz de Cristo es tu ancla. Él calma los vientos y las olas. Confía en Él, y Su paz te sustentará.', verse: 'Marcos 4:39: \'Y levantándose, reprendió al viento, y dijo al mar: Calla, enmudece. Y cesó el viento, y se hizo grande bonanza.\''),
  const Consejo(category: 'Ansiedad', title: 'Descanso en la Ansiedad', description: 'En lugar de preocuparte, descansa en las manos de Dios. Él tiene cuidado de ti y conoce tus necesidades antes de que se las pidas. Su amor es tu seguridad.', verse: '1 Pedro 5:7: \'Echando toda vuestra ansiedad sobre él, porque él tiene cuidado de vosotros.\''),
  const Consejo(category: 'Gratitud', title: 'El Poder de la Alabanza y la Gratitud', description: 'La alabanza y la gratitud son armas poderosas contra la desolación. Expresa tu agradecimiento a Dios en todo momento, y verás cómo tu perspectiva se transforma.', verse: 'Salmo 100:4: \'Entrad por sus puertas con acción de gracias, Por sus atrios con alabanza; Alabadle, bendecid su nombre.\''),
  const Consejo(category: 'PerdÃ³n', title: 'El Perdón Libera', description: 'El perdón no es para el ofensor, es para ti. Te libera de las cadenas de la amargura y te permite experimentar la verdadera libertad en Cristo. Perdona como has sido perdonado.', verse: 'Mateo 6:14-15: \'Porque si perdonáis a los hombres sus ofensas, os perdonará también a vosotros vuestro Padre celestial; mas si no perdonáis a los hombres sus ofensas, tampoco vuestro Padre os perdonará vuestras ofensas.\''),
  const Consejo(category: 'Fe', title: 'Fe en lo Invisible', description: 'La fe te permite ver más allá de las circunstancias visibles y confiar en el Dios invisible que obra en tu favor. Camina por fe, no por vista, en cada paso de tu vida.', verse: '2 Corintios 5:7: \'(porque por fe andamos, no por vista);\''),
  const Consejo(category: 'Relaciones', title: 'Relaciones Basadas en el Amor', description: 'Construye tus relaciones sobre el fundamento del amor de Cristo. Sé paciente, amable, bondadoso y busca siempre el bien del otro. El amor es el lazo perfecto.', verse: 'Colosenses 3:14: \'Y sobre todas estas cosas vestíos de amor, que es el vínculo perfecto.\''),
  const Consejo(category: 'Finanzas', title: 'Principios de Siembra y Cosecha', description: 'Aplica el principio de siembra y cosecha a tus finanzas. Siembra generosamente y con alegría, y Dios te recompensará abundantemente. Confía en Su provisión.', verse: '2 Corintios 9:6: \'Pero esto digo: El que siembra escasamente, también segará escasamente; y el que siembra generosamente, generosamente también segará.\''),
  const Consejo(category: 'DepresiÃ³n', title: 'Dios es tu Consuelo en la Depresión', description: 'Cuando la depresión te envuelva, recuerda que Dios es el Dios de todo consuelo. Él te comprende, te abraza y te ofrece esperanza en medio de tu sufrimiento. Busca Su rostro.', verse: 'Salmo 42:5: \'¿Por qué te abates, oh alma mía, Y te turbas dentro de mí? Espera en Dios, porque aún he de alabarle, Salvación mía y Dios mío.\''),
  const Consejo(category: 'Superar', title: 'Superando Obstáculos con Dios', description: 'No hay obstáculo demasiado grande para Dios. Con Él de tu lado, puedes superar cualquier desafío. Confía en Su poder y en Su fidelidad para abrir camino donde no lo hay.', verse: 'Filipenses 4:13: \'Todo lo puedo en Cristo que me fortalece.\''),
  const Consejo(category: 'Paz', title: 'Buscando la Paz Interior', description: 'La paz interior no es la ausencia de problemas, sino la presencia de Cristo. Cultívala a través de la oración, la meditación en Su Palabra y la entrega de tus cargas a Él.', verse: 'Isaías 26:3: \'Tú guardarás en completa paz a aquel cuyo pensamiento en ti persevera; porque en ti ha confiado.\''),
  const Consejo(category: 'Guia', title: 'Buscando la Guía Divina', description: 'No camines por tu propia cuenta. Pide a Dios dirección en cada decisión. Su Espíritu Santo te guiará a toda verdad y te mostrará el camino que debes seguir.', verse: 'Proverbios 3:5-6: \'Fíate de Jehová de todo tu corazón, y no te apoyes en tu propia prudencia. Reconócelo en todos tus caminos, y él enderezará tus veredas.\''),
  const Consejo(category: 'Pecado', title: 'Lidiando con el Pecado', description: 'Si has caído en pecado, no te quedes en la culpa. Arrepiéntete sinceramente, confiesa tu pecado a Dios y acéptale perdón. Él es fiel para limpiarte y restaurarte.', verse: '1 Juan 1:9: \'Si confesamos nuestros pecados, él es fiel y justo para perdonar nuestros pecados, y limpiarnos de toda maldad.\''),
  const Consejo(category: 'Restauracion', title: 'La Restauración de Dios', description: 'Dios es un Dios de restauración. Él puede tomar tus piezas rotas y restaurar tu vida, tus relaciones y tu esperanza. Confía en Su poder para hacer nuevas todas las cosas.', verse: 'Joel 2:25: \'Y os restituiré los años que comió la oruga, el saltón, el revoltón y la langosta, mi gran ejército que envié contra vosotros.\''),
  const Consejo(category: 'Promesas', title: 'Anclando tu Vida en las Promesas de Dios', description: 'Las promesas de Dios son tu ancla en la tormenta. Estúdialas, medítalas y recuérdalas. Él es fiel para cumplir cada palabra que ha dicho.', verse: '2 Pedro 1:4: \'por medio de las cuales nos ha dado preciosas y grandísimas promesas, para que por ellas llegaseis a ser participantes de la naturaleza divina, habiendo huido de la corrupción que hay en el mundo a causa de la concupiscencia.\''),
  const Consejo(category: 'Fidelidad', title: 'La Fidelidad en el Servicio a Dios', description: 'Sé fiel en las pequeñas cosas y Dios te confiará grandes. Tu fidelidad en el servicio a Él es lo que realmente importa. Persevera y Él te recompensará.', verse: 'Lucas 16:10: \'El que es fiel en lo muy poco, también en lo mucho es fiel; y el que en lo muy poco es injusto, también en lo mucho es injusto.\''),
  const Consejo(category: 'Gozo', title: 'El Gozo del Señor es tu Fortaleza', description: 'El gozo del Señor no depende de las circunstancias, sino de Su presencia en ti. Cultiva un espíritu de gozo, y te dará la fuerza para enfrentar cualquier desafío.', verse: 'Nehemías 8:10: \'Luego les dijo: Id, comed grosuras, y bebed vino dulce, y enviad porciones a los que no tienen nada preparado; porque este día es santo a nuestro Señor; no os entristezcáis, porque el gozo de Jehová es vuestra fuerza.\''),
  const Consejo(category: 'Sufrimiento', title: 'Encontrando Propósito en el Sufrimiento', description: 'El sufrimiento no es en vano. Dios lo usa para moldearte, purificarte y acercarte más a Él. Encuentra consuelo en Su presencia y confía en Su plan.', verse: 'Romanos 5:3-4: \'Y no solo esto, sino que también nos gloriamos en las tribulaciones, sabiendo que la tribulación produce paciencia; y la paciencia, prueba; y la prueba, esperanza;\''),
  const Consejo(category: 'Ansiedad', title: 'La Libertad de la Preocupación', description: 'No te afanes por el mañana. Vive un día a la vez, confiando en la provisión de Dios. Él te librará de la preocupación si echas toda tu ansiedad sobre Él.', verse: 'Mateo 6:34: \'Así que, no os afanéis por el día de mañana, porque el día de mañana traerá su afán. Basta a cada día su propio mal.\''),
  const Consejo(category: 'Adoracion', title: 'Adoración en Espíritu y Verdad', description: 'La adoración va más allá de las canciones; es una actitud del corazón. Adora a Dios con tu vida, tus acciones y tu devoción, en todo momento y lugar.', verse: 'Juan 4:23: \'Mas la hora viene, y ahora es, cuando los verdaderos adoradores adorarán al Padre en espíritu y en verdad; porque también el Padre tales adoradores busca que le adoren.\''),
  const Consejo(category: 'Esperanza', title: 'La Ancla de la Esperanza', description: 'La esperanza en Cristo es el ancla segura para tu alma. En los mares agitados de la vida, aférrate a esa esperanza que no defrauda, porque Él es fiel.', verse: 'Hebreos 6:19: \'La cual tenemos como segura y firme ancla del alma, y que penetra hasta dentro del velo,\''),
  const Consejo(category: 'Disciplina', title: 'La Disciplina del Amor', description: 'La disciplina de Dios es un acto de amor, no de castigo. Confía en Su corrección, porque te moldea para tu bien y te acerca más a Él.', verse: 'Proverbios 3:11-12: \'No menosprecies, hijo mío, el castigo de Jehová, Ni te fatigues de su corrección; Porque Jehová al que ama castiga, Como el padre al hijo a quien quiere.\''),
  const Consejo(category: 'Familia', title: 'Honrando a tu Familia', description: 'Honra a tus padres y a tu familia. Amaos unos a otros con el amor de Cristo, perdonándoos y edificándoos mutuamente. La familia es un diseño divino.', verse: 'Efesios 6:2-3: \'Honra a tu padre y a tu madre, que es el primer mandamiento con promesa; para que te vaya bien, y seas de larga vida sobre la tierra.\''),
  const Consejo(category: 'DepresiÃ³n', title: 'Dios, tu Refugio en la Depresión', description: 'En el abismo de la depresión, Dios es tu roca y tu refugio. Clama a Él, y Él te sacará del pozo de desesperación y pondrá tus pies sobre roca firme.', verse: 'Salmo 40:1-3: \'Pacientemente esperé a Jehová, Y se inclinó a mí, y oyó mi clamor. Y me hizo sacar del pozo de la desesperación, del lodo cenagoso; Puso mis pies sobre peña, y afirmó mis pasos. Puso luego en mi boca cántico nuevo, alabanza a nuestro Dios. Verán esto muchos, y temerán, Y confiarán en Jehová.\''),
  const Consejo(category: 'Envidia', title: 'Superando la Envidia', description: 'La envidia es un veneno para el alma. En lugar de compararte, celebra las bendiciones de los demás y concéntrate en las tuyas. La gratitud es el antídoto.', verse: 'Proverbios 14:30: \'El corazón apacible es vida de la carne; Mas la envidia es carcoma de los huesos.\''),
  const Consejo(category: 'Aceptacion', title: 'La Aceptación Incondicional de Dios', description: 'No tienes que ganarte el amor o la aceptación de Dios. Él te acepta incondicionalmente tal como eres en Cristo. Descansa en Su gracia y Su amor.', verse: 'Romanos 15:7: \'Por tanto, recibíos los unos a los otros, como también Cristo nos recibió, para gloria de Dios.\''),
  const Consejo(category: 'Propósito', title: 'Viviendo con Propósito', description: 'Cada día es una oportunidad para vivir el propósito que Dios tiene para ti. Busca Su voluntad, sírvele con pasión y deja un legado para Su gloria.', verse: 'Jeremías 29:11: \'Porque yo sé los pensamientos que tengo acerca de vosotros, dice Jehová, pensamientos de paz, y no de mal, para daros el fin que esperáis.\''),
  const Consejo(category: 'Crecimiento Espiritual', title: 'Nutriendo tu Espíritu', description: 'Así como nutres tu cuerpo, nutre tu espíritu. Lee la Biblia, ora, ayuna y busca la comunión con otros creyentes para crecer en tu fe.', verse: 'Mateo 4:4: \'Él respondió y dijo: Escrito está: No sólo de pan vivirá el hombre, sino de toda palabra que sale de la boca de Dios.\''),
  const Consejo(category: 'Ansiedad', title: 'Entregando la Ansiedad', description: 'La ansiedad es una carga pesada. Entrégala a Dios, quien tiene el control de todo. Él te dará la fortaleza para enfrentar el día y la paz en tu corazón.', verse: 'Filipenses 4:6: \'Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias.\''),
  const Consejo(category: 'PerdÃ³n', title: 'Un Camino de Perdón', description: 'El perdón es un camino continuo. Perdona como Cristo te ha perdonado, y experimentarás la libertad y la sanidad en tus relaciones.', verse: 'Efesios 4:32: \'Antes sed benignos unos con otros, misericordiosos, perdonándoos unos a otros, como Dios también os perdonó a vosotros en Cristo.\''),
  const Consejo(category: 'Fe', title: 'La Fe que Mueve Montañas', description: 'Con una fe del tamaño de un grano de mostaza, puedes mover montañas. Confía en el poder ilimitado de Dios y en Su capacidad para hacer lo imposible.', verse: 'Mateo 17:20: \'Jesús les dijo: Por vuestra poca fe; porque de cierto os digo, que si tuviereis fe como un grano de mostaza, diréis a este monte: Pásate de aquí allá, y se pasará; y nada os será imposible.\''),
  const Consejo(category: 'Relaciones', title: 'Comunicación en las Relaciones', description: 'La buena comunicación es vital en las relaciones. Habla la verdad en amor, escucha activamente y busca comprender al otro. Honra a Dios en tus palabras.', verse: 'Efesios 4:29: \'Ninguna palabra corrompida salga de vuestra boca, sino la que sea buena para la necesaria edificación, a fin de dar gracia a los oyentes.\''),
  const Consejo(category: 'Finanzas', title: 'Dar con un Corazón Alegre', description: 'La generosidad en tus finanzas no es una obligación, sino un privilegio. Da con un corazón alegre, sabiendo que Dios te bendecirá para ser una bendición para otros.', verse: '2 Corintios 9:7: \'Cada uno dé como propuso en su corazón: no con tristeza, ni por necesidad, porque Dios ama al dador alegre.\''),
  const Consejo(category: 'DepresiÃ³n', title: 'Dios es tu Sanador de la Depresión', description: 'La depresión puede sentirse como una enfermedad del alma, pero Dios es el médico supremo. Clama a Él por sanidad y restauración. Él te levantará.', verse: 'Salmo 30:2: \'Jehová Dios mío, A ti clamé, y me sanaste.\''),
  const Consejo(category: 'Libertad', title: 'La Verdadera Libertad en Cristo', description: 'Cristo te ha hecho verdaderamente libre del pecado, la culpa y la condenación. Vive en esa libertad, no volviendo a la esclavitud, sino sirviendo a Dios y a los demás.', verse: 'Gálatas 5:1: \'Estad, pues, firmes en la libertad con que Cristo nos hizo libres, y no estéis otra vez sujetos al yugo de esclavitud.\''),
  const Consejo(category: 'Paz', title: 'La Paz que Trasciende', description: 'La paz de Dios no es una paz mundana; es una paz que trasciende las circunstancias. Permite que inunde tu corazón y mente, incluso en medio de las pruebas.', verse: 'Colosenses 3:15: \'Y la paz de Dios gobierne en vuestros corazones, a la que asimismo fuisteis llamados en un solo cuerpo; y sed agradecidos.\''),
  const Consejo(category: 'Humildad', title: 'La Humildad Abre Puertas', description: 'La humildad es la llave que abre puertas de bendición y gracia. Cuando te humillas ante Dios, Él te exalta. Humíllate y sirve a los demás.', verse: 'Santiago 4:10: \'Humillaos delante del Señor, y él os exaltará.\''),
  const Consejo(category: 'Justicia Social', title: 'Buscando la Justicia Social', description: 'Los cristianos están llamados a buscar la justicia y a defender a los oprimidos. Actúa con compasión y trabaja por la equidad en tu comunidad y en el mundo.', verse: 'Isaías 1:17: \'Aprended a hacer el bien; buscad el juicio, restituid al agraviado, haced justicia al huérfano, amparad a la viuda.\''),
  const Consejo(category: 'Unidad', title: 'La Unidad en el Cuerpo de Cristo', description: 'La unidad es esencial en la iglesia. Busca la armonía, resuelve las diferencias en amor y trabaja juntos para el avance del Reino de Dios.', verse: 'Efesios 4:3: \'solícitos en guardar la unidad del Espíritu en el vínculo de la paz;\''),
  const Consejo(category: 'Agradecimiento', title: 'Un Corazón Lleno de Agradecimiento', description: 'Un corazón agradecido es un corazón feliz. Da gracias a Dios por Sus bondades, grandes y pequeñas, y Su gozo llenará tu vida.', verse: 'Salmo 9:1: \'Te alabaré, oh Jehová, con todo mi corazón; Contaré todas tus maravillas.\''),
  const Consejo(category: 'Propósito', title: 'Encontrando Tu Lugar en el Plan de Dios', description: 'No eres un accidente. Dios te creó con un propósito único. Búscalo a Él para entender tu lugar en Su gran plan y vive para Su gloria.', verse: 'Efesios 2:10: \'Porque somos hechura suya, creados en Cristo Jesús para buenas obras, las cuales Dios preparó de antemano para que anduviésemos en ellas.\''),
  const Consejo(category: 'Compasion', title: 'Mostrando Compasión a Otros', description: 'Imita la compasión de Cristo. Ten un corazón sensible a las necesidades de los demás, y extiende ayuda práctica y amor a quienes te rodean.', verse: 'Mateo 9:36: \'Y al ver las multitudes, tuvo compasión de ellas; porque estaban desamparadas y dispersas como ovejas que no tienen pastor.\''),
  const Consejo(category: 'Paz Mental', title: 'La Paz que Sobrepasa', description: 'La paz mental no es un mito. Es una promesa de Dios para aquellos que confían en Él. Entrega tus preocupaciones y Él guardará tu mente y corazón.', verse: 'Filipenses 4:7: \'Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.\''),
  const Consejo(category: 'PerdÃ³n', title: 'La Gracia del Perdón', description: 'El perdón es una expresión de la gracia de Dios en tu vida. Extiéndela a los demás, incluso a los que te han lastimado, y experimenta la libertad que solo el perdón puede dar.', verse: 'Lucas 6:37: \'No juzguéis, y no seréis juzgados; no condenéis, y no seréis condenados; perdonad, y seréis perdonados.\''),
  const Consejo(category: 'Fe', title: 'La Fe es Acción', description: 'La fe no es solo creer, es actuar en base a lo que crees. Demuestra tu fe con tus obras, y verás cómo Dios obra poderosamente a través de ti.', verse: 'Santiago 2:17: \'Así también la fe, si no tiene obras, es muerta en sí misma.\''),
  const Consejo(category: 'Relaciones', title: 'Amor Genuino en las Relaciones', description: 'Ama sin hipocresía. Sé sincero y genuino en tus relaciones, mostrando el amor de Cristo a todos los que te rodean. La honestidad construye puentes.', verse: 'Romanos 12:9-10: \'El amor sea sin fingimiento. Aborreced lo malo, seguid lo bueno. Amaos los unos a los otros con amor fraternal; en cuanto a honra, prefiriéndoos los unos a los otros.\''),
  const Consejo(category: 'Finanzas', title: 'Liberándote de la Deuda', description: 'La deuda puede ser una carga. Busca la sabiduría de Dios para administrar tus finanzas, evita las deudas innecesarias y esfuérzate por vivir dentro de tus posibilidades.', verse: 'Proverbios 22:7: \'El rico se enseñorea de los pobres, Y el que toma prestado es siervo del que presta.\''),
  const Consejo(category: 'DepresiÃ³n', title: 'Dios es tu Fuerza en la Debilidad', description: 'Cuando te sientas débil por la depresión, recuerda que la fuerza de Dios se perfecciona en tu debilidad. Apóyate en Él, y Él te levantará y te sustentará.', verse: '2 Corintios 12:9-10: \'Y me ha dicho: Bástate mi gracia; porque mi poder se perfecciona en la debilidad. Por tanto, de buena gana me gloriaré más bien en mis debilidades, para que repose sobre mí el poder de Cristo. Por lo cual, por amor a Cristo me gozo en las debilidades, en afrentas, en necesidades, en persecuciones, en angustias; porque cuando soy débil, entonces soy fuerte.\''),
  const Consejo(category: 'Miedo', title: 'El Amor Perfecto Ahuyenta el Miedo', description: 'El miedo no puede coexistir con el amor perfecto de Dios. Deja que Su amor inunde tu corazón y expulse todo temor de tu vida. Él está contigo.', verse: '1 Juan 4:18: \'En el amor no hay temor, sino que el perfecto amor echa fuera el temor; porque el temor lleva en sí castigo. De donde el que teme, no ha sido perfeccionado en el amor.\''),
  const Consejo(category: 'Santidad', title: 'Persiguiendo la Santidad', description: 'La santidad es un llamado para cada creyente. Es un proceso de separarte del mundo y vivir para Dios. Esfuérzate por ser santo en todas tus acciones.', verse: 'Hebreos 12:14: \'Seguid la paz con todos, y la santidad, sin la cual nadie verá al Señor.\''),
  const Consejo(category: 'Contentamiento', title: 'El Secreto del Contentamiento', description: 'El secreto del contentamiento no es tener más, sino desear menos y confiar en la provisión de Dios. Aprende a estar satisfecho en todas las circunstancias.', verse: 'Filipenses 4:11-12: \'No lo digo porque tenga escasez, pues he aprendido a contentarme, cualquiera que sea mi situación; sé vivir humildemente, y sé tener abundancia; en todo y por todo estoy enseñado, así para estar saciado como para tener hambre, así para tener abundancia como para padecer necesidad.\''),
  const Consejo(category: 'Integridad', title: 'Viviendo con Integridad', description: 'Tu integridad es un testimonio de tu fe. Sé honesto, justo y transparente en todo lo que haces, para que tu vida glorifique a Dios.', verse: 'Proverbios 10:9: \'El que camina en integridad anda confiado; Mas el que pervierte sus caminos será quebrantado.\''),
  const Consejo(category: 'Oracion', title: 'La Oración como Aliento de Vida', description: 'La oración es el aliento de vida del creyente. Haz de ella una parte constante de tu día, hablando con Dios y escuchando Su voz.', verse: '1 Tesalonicenses 5:17: \'Orad sin cesar.\''),
  const Consejo(category: 'Obediencia', title: 'La Obediencia Trae Bendición', description: 'Obedece a Dios en todas las áreas de tu vida. La obediencia no es un sacrificio, sino un camino hacia la plenitud y la bendición que Él tiene para ti.', verse: 'Deuteronomio 28:1-2: \'Acontecerá que si oyeres atentamente la voz de Jehová tu Dios, para guardar y poner por obra todos sus mandamientos que yo te prescribo hoy, también Jehová tu Dios te exaltará sobre todas las naciones de la tierra. Y vendrán sobre ti todas estas bendiciones, y te alcanzarán, si oyeres la voz de Jehová tu Dios.\''),
  const Consejo(category: 'Identidad', title: 'Eres Amado por Dios', description: 'Tu identidad no está en lo que el mundo dice de ti, sino en que eres un hijo amado de Dios. Descansa en Su amor incondicional y en quién te ha hecho ser.', verse: 'Juan 1:12: \'Mas a todos los que le recibieron, a los que creen en su nombre, les dio potestad de ser hechos hijos de Dios;\''),
  const Consejo(category: 'Promesas', title: 'Aferrándote a las Promesas', description: 'En medio de la incertidumbre, aférrate a las inmutables promesas de Dios. Él es fiel para cumplir cada una de ellas en Su tiempo perfecto.', verse: '2 Corintios 1:20: \'porque todas las promesas de Dios son en él Sí, y en él Amén, por medio de nosotros, para la gloria de Dios.\''),
  const Consejo(category: 'Matrimonio', title: 'Amor y Respeto en el Matrimonio', description: 'El amor y el respeto son pilares del matrimonio. Maridos, amad a vuestras mujeres; mujeres, respetad a vuestros maridos. Honrad a Cristo en vuestra unión.', verse: 'Efesios 5:33: \'Por lo demás, cada uno de vosotros ame también a su mujer como a sí mismo; y la mujer respete a su marido.\''),
  const Consejo(category: 'Crianza', title: 'Criando Hijos con Amor y Verdad', description: 'Educa a tus hijos con amor firme y la verdad de la Palabra de Dios. Sé su ejemplo, guíalos en justicia y ora por ellos constantemente.', verse: 'Efesios 6:4: \'Y vosotros, padres, no provoquéis a ira a vuestros hijos, sino criadlos en disciplina y amonestación del Señor.\''),
  const Consejo(category: 'Trabajo', title: 'Trabajando con Propósito', description: 'Tu trabajo no es solo un medio para un fin, es una oportunidad para glorificar a Dios. Trabaja con diligencia y excelencia, como para Él, en todo lo que hagas.', verse: 'Colosenses 3:23: \'Y todo lo que hagáis, hacedlo de corazón, como para el Señor y no para los hombres;\''),
  const Consejo(category: 'Salvacion', title: 'La Plenitud de la Salvación', description: 'La salvación es un regalo completo de Dios: perdón de pecados, nueva vida y la promesa de la eternidad. Recíbela por fe y vive en Su libertad.', verse: 'Juan 3:16: \'Porque de tal manera amó Dios al mundo, que ha dado a su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna.\''),
  const Consejo(category: 'Evangelismo', title: 'Sembrando Semillas del Evangelio', description: 'No subestimes el poder de una palabra amable o un testimonio personal. Siembra semillas del evangelio con amor y Dios hará crecer la cosecha en Su tiempo.', verse: '1 Corintios 3:6-7: \'Yo planté, Apolos regó; pero el crecimiento lo ha dado Dios. Así que ni el que planta es algo, ni el que riega, sino Dios, que da el crecimiento.\''),
  const Consejo(category: 'Confianza', title: 'Confía en el Plan de Dios', description: 'Cuando la vida parezca incierta, confía en que Dios tiene un plan perfecto. Él conoce el futuro y te guiará paso a paso si le entregas el control.', verse: 'Jeremías 29:11: \'Porque yo sé los pensamientos que tengo acerca de vosotros, dice Jehová, pensamientos de paz, y no de mal, para daros el fin que esperáis.\''),
  const Consejo(category: 'Paz', title: 'La Paz de Dios en tu Corazón', description: 'Permite que la paz de Dios, que sobrepasa todo entendimiento, sea el árbitro en tu corazón. Elige la paz sobre la preocupación en cada situación.', verse: 'Colosenses 3:15: \'Y la paz de Dios gobierne en vuestros corazones, a la que asimismo fuisteis llamados en un solo cuerpo; y sed agradecidos.\''),
  const Consejo(category: 'Gozo', title: 'Un Gozo Inquebrantable', description: 'El gozo del Señor es tu fuerza, no es superficial, sino profundo y duradero. Se encuentra en Su presencia, incluso en medio de las pruebas más difíciles.', verse: 'Salmo 16:11: \'Me mostrarás la senda de la vida; En tu presencia hay plenitud de gozo; Delicias a tu diestra para siempre.\''),
  const Consejo(category: 'Mente', title: 'Controlando tus Pensamientos', description: 'La batalla por tu paz comienza en tu mente. Toma cautivo cada pensamiento y somételo a Cristo. Llena tu mente con la verdad de Su Palabra.', verse: '2 Corintios 10:5: \'derribando argumentos y toda altivez que se levanta contra el conocimiento de Dios, y llevando cautivo todo pensamiento a la obediencia a Cristo,\''),
  const Consejo(category: 'Sabiduria', title: 'La Sabiduría es Mejor que el Oro', description: 'Busca la sabiduría de Dios por encima de todo tesoro. Te guiará, te protegerá y te dará discernimiento para tomar decisiones que glorifiquen Su nombre.', verse: 'Proverbios 3:13-15: \'Bienaventurado el hombre que halla la sabiduría, Y que obtiene la inteligencia; Porque su ganancia es mejor que la ganancia de la plata, Y sus frutos más que el oro fino. Más preciosa es que las piedras preciosas; Y todo lo que puedes desear, no se puede comparar a ella.\''),
  const Consejo(category: 'Amor', title: 'El Amor Edifica', description: 'El amor no es solo un sentimiento, es una acción. Edifica a los demás con tus palabras y tus hechos, y demuestra el amor de Cristo en cada interacción.', verse: '1 Corintios 8:1: \'En cuanto a lo sacrificado a los ídolos, sabemos que todos tenemos conocimiento. El conocimiento envanece, pero el amor edifica.\''),
  const Consejo(category: 'Esperanza', title: 'Manteniendo la Esperanza Viva', description: 'En un mundo lleno de desesperanza, tú tienes una esperanza viva en Cristo. Manténla encendida, compártela con otros y vive cada día con expectativa de Su regreso.', verse: '1 Pedro 1:3: \'Bendito el Dios y Padre de nuestro Señor Jesucristo, que según su grande misericordia nos hizo renacer para una esperanza viva, por la resurrección de Jesucristo de los muertos;\''),
  const Consejo(category: 'Disciplina', title: 'La Disciplina Te Hace Fuerte', description: 'Acepta la disciplina de Dios como un entrenamiento para tu crecimiento. Te hará más fuerte, más sabio y más parecido a Cristo en tu caminar.', verse: 'Hebreos 12:11: \'Es verdad que ninguna disciplina al presente parece ser causa de gozo, sino de tristeza; pero después da fruto apacible de justicia a los que por ella han sido ejercitados.\''),
  const Consejo(category: 'Amistad', title: 'Sé un Amigo Fiel', description: 'Sé el tipo de amigo que siempre está ahí, en las buenas y en las malas. Un amigo fiel es un tesoro. Invierte en amistades que honren a Dios.', verse: 'Proverbios 17:17: \'En todo tiempo ama el amigo, Y es como un hermano en tiempo de angustia.\''),
  const Consejo(category: 'DepresiÃ³n', title: 'Dios te Sostiene en la Depresión', description: 'Cuando la depresión te arrastre, siente los brazos de Dios sosteniéndote. Él es tu roca inmovible y tu refugio seguro en la tormenta. Clama a Él.', verse: 'Salmo 73:26: \'Mi carne y mi corazón desfallecen; Mas la roca de mi corazón y mi porción es Dios para siempre.\''),
  const Consejo(category: 'PerdÃ³n', title: 'Perdón: Un Puente a la Libertad', description: 'El perdón es un puente que te lleva de la prisión del resentimiento a la libertad. Cruza ese puente, libera a quienes te hirieron y libérate a ti mismo.', verse: 'Mateo 18:21-22: \'Entonces se le acercó Pedro y le dijo: Señor, ¿cuántas veces perdonaré a mi hermano que peque contra mí? ¿Hasta siete? Jesús le dijo: No te digo hasta siete, sino aun hasta setenta veces siete.\''),
  const Consejo(category: 'Fe', title: 'La Fe es la Victoria', description: 'Tu fe en Cristo es la victoria que vence al mundo. Permanece firme, confía en Su poder y mira cómo Él te lleva a la victoria en cada batalla.', verse: '1 Juan 5:4: \'Porque todo lo que es nacido de Dios vence al mundo; y esta es la victoria que ha vencido al mundo, nuestra fe.\''),
  const Consejo(category: 'Relaciones', title: 'Amor y Respeto en las Relaciones', description: 'Las relaciones saludables se construyen sobre el amor y el respeto mutuo. Honra a los demás, escucha sus perspectivas y busca la armonía en Cristo.', verse: 'Romanos 12:10: \'Amaos los unos a los otros con amor fraternal; en cuanto a honra, prefiriéndoos los unos a los otros.\''),
  const Consejo(category: 'Finanzas', title: 'Honrando a Dios con tus Finanzas', description: 'Honra a Dios con tus finanzas dándole el primer lugar. Sé un mayordomo fiel de lo que Él te ha dado, y verás Su bendición sobre tu vida.', verse: 'Proverbios 3:9-10: \'Honra a Jehová con tus bienes, Y con las primicias de todos tus frutos; Y serán llenos tus graneros con abundancia, Y tus lagares rebosarán de mosto.\''),
  const Consejo(category: 'Miedo', title: 'Sin Miedo, Con Coraje', description: 'Dios no te ha dado un espíritu de cobardía, sino de coraje. Enfréntate a tus miedos con fe, sabiendo que Él está contigo y te capacita para ser valiente.', verse: 'Josué 1:9: \'Mira que te mando que te esfuerces y seas valiente; no temas ni desmayes, porque Jehová tu Dios estará contigo en dondequiera que vayas.\''),
  const Consejo(category: 'Paz Interior', title: 'Encontrando la Calma Interior', description: 'En el ajetreo de la vida, busca la calma interior en la presencia de Dios. Él te dará un descanso para tu alma y una paz que el mundo no puede dar.', verse: 'Mateo 11:28-30: \'Venid a mí todos los que estáis trabajados y cargados, y yo os haré descansar. Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso para vuestras almas; porque mi yugo es fácil, y ligera mi carga.\''),
  const Consejo(category: 'Tristeza', title: 'La Consolidación en la Tristeza', description: 'Dios es tu Consolador en la tristeza más profunda. No temas expresarle tu dolor. Él te escucha y te abraza con Su amor. Su Espíritu te fortalecerá.', verse: 'Salmo 30:5: \'Porque un momento será su ira, Pero su favor dura toda la vida. Por la noche durará el lloro, Y a la mañana vendrá la alegría.\''),
  const Consejo(category: 'Generosidad', title: 'La Generosidad Abre los Cielos', description: 'La generosidad es un principio del reino de Dios. Cuando das con un corazón desprendido, Dios abre las ventanas de los cielos y derrama bendiciones sobre ti.', verse: 'Malaquías 3:10: \'Traed todos los diezmos al alfolí y haya alimento en mi casa; y probadme ahora en esto, dice Jehová de los ejércitos, si no os abriré las ventanas de los cielos, y derramaré sobre vosotros bendición hasta que sobreabunde.\''),
  const Consejo(category: 'Humildad', title: 'El Camino de la Humildad', description: 'El camino hacia la verdadera grandeza es la humildad. Sigue el ejemplo de Cristo, quien se humilló a sí mismo. Sirve a los demás con un corazón humilde.', verse: 'Filipenses 2:3-4: \'Nada hagáis por contienda o por vanagloria; antes bien con humildad, estimando cada uno a los demás como superiores a sí mismo; no mirando cada uno por lo suyo propio, sino cada cual también por lo de los otros.\''),
  const Consejo(category: 'Fidelidad', title: 'Fidelidad en los Pequeños Detalles', description: 'La fidelidad se demuestra en los pequeños detalles de la vida. Sé fiel en tus responsabilidades, tus compromisos y tu servicio, y Dios te recompensará.', verse: 'Lucas 16:10: \'El que es fiel en lo muy poco, también en lo mucho es fiel; y el que en lo muy poco es injusto, también en lo mucho es injusto.\''),
  const Consejo(category: 'Paciencia', title: 'La Paciencia Florece en la Prueba', description: 'La paciencia no es la capacidad de esperar, sino de mantener una buena actitud mientras esperas. Florece en medio de las pruebas, produciendo carácter.', verse: 'Romanos 5:3-4: \'Y no solo esto, sino que también nos gloriamos en las tribulaciones, sabiendo que la tribulación produce paciencia; y la paciencia, prueba; y la prueba, esperanza.\''),
  const Consejo(category: 'Gozo', title: 'El Gozo Restaurado', description: 'Si has perdido el gozo, clama a Dios. Él es fiel para restaurar tu alma y llenar tu corazón con Su gozo inquebrantable. Él es la fuente de todo bien.', verse: 'Salmo 51:12: \'Vuélveme el gozo de tu salvación, Y espíritu noble me sustente.\''),
  const Consejo(category: 'PerdÃ³n', title: 'Perdonar es Soltar', description: 'Perdonar es soltar la ofensa y liberarte a ti mismo del peso del resentimiento. Elige perdonar, y experimentarás la libertad que solo viene de Cristo.', verse: 'Marcos 11:25: \'Y cuando estéis orando, perdonad, si tenéis algo contra alguno, para que también vuestro Padre que está en los cielos os perdone a vosotros vuestras ofensas.\''),
  const Consejo(category: 'Fe', title: 'Caminar por Fe', description: 'La vida cristiana es un caminar por fe. Confía en Dios incluso cuando no veas el camino. Él te guiará paso a paso, abriendo puertas y cerrando otras.', verse: '2 Corintios 5:7: \'(porque por fe andamos, no por vista);\''),
  const Consejo(category: 'Relaciones', title: 'El Amor Cubre Multitud de Faltas', description: 'En las relaciones, el amor genuino es la clave. Cubre las faltas de los demás con amor, sé paciente y busca siempre la reconciliación y la paz.', verse: '1 Pedro 4:8: \'Y ante todo, tened entre vosotros ferviente amor; porque el amor cubrirá multitud de pecados.\''),
  const Consejo(category: 'Finanzas', title: 'El Principio del Diezmo', description: 'El diezmo es un acto de fe y obediencia a Dios. Honra a Él con la primera parte de tus ingresos, y Él te bendecirá y abrirá las ventanas de los cielos.', verse: 'Malaquías 3:10: \'Traed todos los diezmos al alfolí y haya alimento en mi casa; y probadme ahora en esto, dice Jehová de los ejércitos, si no os abriré las ventanas de los cielos, y derramaré sobre vosotros bendición hasta que sobreabunde.\''),
  const Consejo(category: 'DepresiÃ³n', title: 'Un Nuevo Amanecer en la Depresión', description: 'Cada día es una oportunidad para un nuevo amanecer en tu lucha contra la depresión. Busca la luz de Cristo, quien disipa las tinieblas y te da esperanza para un nuevo comienzo.', verse: 'Lamentaciones 3:22-23: \'Por la misericordia de Jehová no hemos sido consumidos, porque nunca decayeron sus misericordias. Nuevas son cada mañana; grande es tu fidelidad.\''),
  const Consejo(category: 'Miedo', title: 'Venciendo el Miedo al Futuro', description: 'No temas al futuro, porque Dios ya está allí. Él tiene planes de bien para ti. Confía en Su soberanía y Su amor, y Él te guiará paso a paso.', verse: 'Jeremías 29:11: \'Porque yo sé los pensamientos que tengo acerca de vosotros, dice Jehová, pensamientos de paz, y no de mal, para daros el fin que esperáis.\''),
  const Consejo(category: 'Esperanza', title: 'La Esperanza Nunca Fallará', description: 'La esperanza en Cristo nunca fallará. Es una esperanza que se basa en Su fidelidad y Sus promesas eternas. Aférrate a ella en cada temporada de tu vida.', verse: 'Romanos 5:5: \'y la esperanza no avergüenza; porque el amor de Dios ha sido derramado en nuestros corazones por el Espíritu Santo que nos fue dado.\''),
  const Consejo(category: 'Paz Interior', title: 'Encontrando Tu Centro de Paz', description: 'Encuentra tu centro de paz en Cristo. No permitas que el ruido del mundo perturbe tu interior. Permanece en Su presencia y experimenta Su calma.', verse: 'Juan 14:27: \'La paz os dejo, mi paz os doy; yo no os la doy como el mundo la da. No se turbe vuestro corazón, ni tenga miedo.\''),
  const Consejo(category: 'Soledad', title: 'Dios, el Compañero Perfecto', description: 'Cuando te sientas solo, recuerda que Dios es el compañero perfecto. Él está siempre contigo, te comprende y te ama incondicionalmente. Búscale en todo momento.', verse: 'Hebreos 13:5: \'Sean vuestras costumbres sin avaricia, contentos con lo que tenéis ahora; porque él dijo: No te desampararé, ni te dejaré;\''),
  const Consejo(category: 'Duda', title: 'La Duda es una Oportunidad para Crecer', description: 'No temas a la duda; úsala como una oportunidad para buscar más a Dios y fortalecer tu fe. Él revelará Su verdad a un corazón sincero.', verse: 'Juan 20:29: \'Jesús le dijo: Porque me has visto, Tomás, creíste; bienaventurados los que no vieron, y creyeron.\''),
  const Consejo(category: 'PerdÃ³n', title: 'El Poder Sanador del Perdón', description: 'El perdón tiene un poder sanador para el que perdona y para el perdonado. Rompe las cadenas del resentimiento y abre la puerta a la restauración.', verse: 'Mateo 6:14: \'Porque si perdonáis a los hombres sus ofensas, os perdonará también a vosotros vuestro Padre celestial;\''),
  const Consejo(category: 'Integridad', title: 'La Integridad Define tu Carácter', description: 'Tu integridad es la base de tu carácter. Vive de manera que tus palabras y tus acciones estén alineadas con la verdad y la justicia de Dios.', verse: 'Proverbios 11:3: \'La integridad de los rectos los encaminará; pero la perversidad de los prevaricadores los destruirá.\''),
  const Consejo(category: 'Oracion', title: 'La Oración Transforma', description: 'La oración es una herramienta poderosa que transforma corazones, circunstancias y vidas. Ora con fe, perseverancia y la convicción de que Dios te escucha.', verse: 'Santiago 5:16: \'Confesaos vuestras ofensas unos a otros, y orad unos por otros, para que seáis sanados. La oración eficaz del justo puede mucho.\''),
  const Consejo(category: 'Obediencia', title: 'Obedecer es Mejor que Sacrificio', description: 'Dios valora la obediencia más que cualquier sacrificio. Demuestra tu amor por Él obedeciendo Su Palabra, y experimentarás Sus ricas bendiciones.', verse: '1 Samuel 15:22: \'Y Samuel dijo: ¿Se complace Jehová tanto en los holocaustos y víctimas, como en que se obedezca a las palabras de Jehová? Ciertamente el obedecer es mejor que los sacrificios, y el prestar atención que la grosura de los carneros.\''),
  const Consejo(category: 'Adversidad', title: 'Fortaleza en la Adversidad', description: 'La adversidad no es el final, es una oportunidad para que la fortaleza de Dios se manifieste en ti. Permanece firme, y Él te sostendrá.', verse: 'Isaías 41:10: \'No temas, porque yo estoy contigo; no desmayes, porque yo soy tu Dios que te esfuerzo; siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia.\''),
  const Consejo(category: 'Consuelo', title: 'El Consuelo en Toda Tribulación', description: 'Dios es el Dios de todo consuelo, listo para abrazarte en cada tribulación. Recibe Su consuelo, y luego úsalo para consolar a otros.', verse: '2 Corintios 1:3-4: \'Bendito sea el Dios y Padre de nuestro Señor Jesucristo, Padre de misericordias y Dios de toda consolación, el cual nos consuela en todas nuestras tribulaciones, para que podamos también nosotros consolar a los que están en cualquier tribulación, por medio de la consolación con que nosotros somos consolados por Dios.\''),
  const Consejo(category: 'Liderazgo', title: 'Liderazgo de Servicio', description: 'El liderazgo en el reino de Dios es un llamado al servicio. Lidera con humildad, con un corazón de siervo, buscando el bienestar de aquellos a quienes sirves.', verse: 'Marcos 10:45: \'Porque el Hijo del Hombre no vino para ser servido, sino para servir, y para dar su vida en rescate por muchos.\''),
  const Consejo(category: 'Identidad', title: 'Tu Valor en Cristo', description: 'Tu valor no está en tus logros o posesiones, sino en quién eres en Cristo. Eres una creación amada y valiosa, hecha a Su imagen. Vive en esa verdad.', verse: 'Salmo 139:14: \'Te alabaré; porque formidables, maravillosas son tus obras; Estoy asombrado, Y mi alma lo sabe muy bien.\''),
  const Consejo(category: 'Promesas', title: 'Las Promesas: Tu Roca Firme', description: 'Las promesas de Dios son tu roca firme en un mundo cambiante. Constrúyete sobre ellas, y tu vida será inquebrantable. Él es fiel para cumplirlas.', verse: 'Josué 21:45: \'No faltó palabra de todas las buenas promesas que Jehová había hecho a la casa de Israel; todo se cumplió.\''),
  const Consejo(category: 'Matrimonio', title: 'El Matrimonio: Un Cordón de Tres Dobleces', description: 'Un matrimonio centrado en Cristo es un cordón de tres dobleces que no se rompe fácilmente. Invita a Dios a ser el centro de tu relación y Él la fortalecerá.', verse: 'Eclesiastés 4:12: \'Y si alguno prevaleciere contra uno, dos le resistirán; y cordón de tres dobleces no se rompe pronto.\''),
  const Consejo(category: 'Crianza', title: 'El Corazón del Padre', description: 'Como padres, reflejen el corazón de nuestro Padre celestial. Amen, guíen y disciplinen a sus hijos con sabiduría y gracia, enseñándoles los caminos del Señor.', verse: 'Proverbios 1:8: \'Oye, hijo mío, la instrucción de tu padre, Y no desprecies la dirección de tu madre;\''),
  const Consejo(category: 'Trabajo', title: 'La Santidad en el Trabajo', description: 'Tu lugar de trabajo puede ser un campo misionero. Vive tu fe con integridad y excelencia, y sé una luz en tu entorno laboral para la gloria de Dios.', verse: '1 Tesalonicenses 4:11-12: \'y que procuréis tener tranquilidad, y ocuparos en vuestros negocios, y trabajar con vuestras manos de la manera que os hemos mandado, a fin de que os conduzcáis honradamente para con los de afuera, y no tengáis necesidad de nada.\''),
  const Consejo(category: 'Salvacion', title: 'La Seguridad de la Salvación', description: 'Una vez que has recibido a Cristo, tu salvación es segura. Descansa en la obra terminada de Jesús en la cruz y vive en la seguridad de Su amor eterno.', verse: 'Juan 10:28-29: \'Y yo les doy vida eterna; y no perecerán jamás, ni nadie las arrebatará de mi mano. Mi Padre que me las dio, es mayor que todos, y nadie las puede arrebatar de la mano de mi Padre.\''),
  const Consejo(category: 'Evangelismo', title: 'Un Testigo Viviente', description: 'Sé un testigo viviente de Cristo a través de tu vida. Tus acciones hablan más fuerte que tus palabras. Vive de tal manera que otros deseen conocer a Dios.', verse: 'Mateo 5:16: \'Así alumbre vuestra luz delante de los hombres, para que vean vuestras buenas obras, y glorifiquen a vuestro Padre que está en los cielos.\''),
  const Consejo(category: 'Sanidad', title: 'La Fe para Sanidad', description: 'Dios es el mismo ayer, hoy y siempre. Él aún sana. Clama a Él con fe por sanidad, ya sea física, emocional o espiritual. Su poder no tiene límites.', verse: 'Marcos 16:17-18: \'Y estas señales seguirán a los que creen: En mi nombre echarán fuera demonios; hablarán nuevas lenguas; tomarán en las manos serpientes; y si bebieren cosa mortífera, no les hará daño; sobre los enfermos pondrán sus manos, y sanarán.\''),
  const Consejo(category: 'Muerte', title: 'La Victoria sobre la Muerte', description: 'Por medio de Cristo, la muerte ha sido vencida. Para el creyente, es la puerta a la vida eterna. Alégrate en esta victoria y consuélate en Su promesa.', verse: '1 Corintios 15:54-57: \'Y cuando esto corruptible se haya vestido de incorrupción, y esto mortal se haya vestido de inmortalidad, entonces se cumplirá la palabra que está escrita: Sorbida es la muerte en victoria. ¿Dónde está, oh muerte, tu aguijón? ¿Dónde, oh sepulcro, tu victoria? Ya el aguijón de la muerte es el pecado, y el poder del pecado, la ley. Mas gracias sean a Dios, que nos da la victoria por medio de nuestro Señor Jesucristo.\''),
  const Consejo(category: 'Guerra Espiritual', title: 'Mantente Firme en la Guerra Espiritual', description: 'La guerra espiritual es real, pero no estás solo. Mantente firme en la armadura de Dios, ora con diligencia y resiste al enemigo con la verdad y la fe.', verse: 'Efesios 6:13-18: \'Por tanto, tomad toda la armadura de Dios, para que podáis resistir en el día malo, y habiendo acabado todo, estar firmes. Estad, pues, firmes, ceñidos vuestros lomos con la verdad, y vestidos con la coraza de justicia, y calzados los pies con el apresto del evangelio de la paz. Sobre todo, tomad el escudo de la fe, con que podáis apagar todos los dardos de fuego del maligno; y tomad el yelmo de la salvación, y la espada del Espíritu, que es la palabra de Dios; orando en todo tiempo con toda oración y súplica en el Espíritu, y velando en ello con toda perseverancia y súplica por todos los santos;\''),
  const Consejo(category: 'Adicciones', title: 'Rompiendo las Cadenas de la Adicción', description: 'La adicción no tiene que definirte. A través de Cristo, puedes romper las cadenas y experimentar la verdadera libertad. Busca ayuda y apóyate en Su poder transformador.', verse: 'Gálatas 5:1: \'Estad, pues, firmes en la libertad con que Cristo nos hizo libres, y no estéis otra vez sujetos al yugo de esclavitud.\''),
  const Consejo(category: 'Temor del Hombre', title: 'Libre del Temor al Hombre', description: 'No permitas que el temor al juicio o la aprobación de los hombres te controle. Tu única audiencia es Dios. Vive para agradarle a Él, y serás verdaderamente libre.', verse: 'Hechos 5:29: \'Respondiendo Pedro y los apóstoles, dijeron: Es necesario obedecer a Dios antes que a los hombres.\''),
  const Consejo(category: 'Mentira', title: 'Viviendo en la Verdad', description: 'La verdad te hará libre. Vive en la verdad de la Palabra de Dios y habla la verdad con amor, incluso cuando sea difícil. La honestidad es un sello de Cristo.', verse: 'Juan 8:32: \'y conoceréis la verdad, y la verdad os hará libres.\''),
  const Consejo(category: 'Desempleo', title: 'Dios, Tu Proveedor Fiel', description: 'En tiempos de desempleo, recuerda que Dios es tu proveedor fiel. Él conoce tus necesidades y abrirá puertas que nadie puede cerrar. Confía en Su provisión.', verse: 'Mateo 6:26: \'Mirad las aves del cielo, que no siembran, ni siegan, ni recogen en graneros; y sin embargo, vuestro Padre celestial las alimenta. ¿No valéis vosotros mucho más que ellas?\''),
  const Consejo(category: 'Abuso', title: 'Sanidad de Heridas de Abuso', description: 'Las heridas del abuso pueden ser profundas, pero Dios es el Gran Sanador. Busca Su restauración, perdona si es posible y permite que Él sane tu corazón y tu mente.', verse: 'Salmo 147:3: \'Él sana a los quebrantados de corazón, Y venda sus heridas.\''),
  const Consejo(category: 'Divorcio', title: 'Gracia para el Divorciado', description: 'Dios tiene gracia para el divorciado. Aunque el divorcio no es Su plan ideal, Él puede restaurar y usar tu vida de maneras poderosas. Confía en Su amor y perdón.', verse: 'Isaías 61:3: \'a ordenar a los afligidos de Sion; a darles gloria en lugar de ceniza, óleo de gozo en lugar de luto, manto de alegría en lugar del espíritu angustiado; y serán llamados árboles de justicia, plantío de Jehová, para gloria suya.\''),
  const Consejo(category: 'Perdida de un Hijo', title: 'La Esperanza en la Pérdida', description: 'En la inmensa tristeza de perder un hijo, aferrate a la esperanza de la resurrección en Cristo. Un día, en Su presencia, todas las lágrimas serán enjugadas.', verse: '1 Tesalonicenses 4:13-14: \'Tampoco queremos, hermanos, que ignoréis acerca de los que duermen, para que no os entristezcáis como los otros que no tienen esperanza. Porque si creemos que Jesús murió y resucitó, así también traerá Dios con Jesús a los que durmieron en él.\''),
  const Consejo(category: 'Rechazo', title: 'El Amor de Dios te Sostiene', description: 'Cuando te sientas rechazado, recuerda el amor incondicional de Dios por ti. Él nunca te abandonará ni te dejará. Eres Su valiosa posesión.', verse: 'Romanos 8:38-39: \'Por lo cual estoy seguro de que ni la muerte, ni la vida, ni ángeles, ni principados, ni potestades, ni lo presente, ni lo por venir, ni lo alto, ni lo profundo, ni ninguna otra cosa creada nos podrá separar del amor de Dios, que es en Cristo Jesús Señor nuestro.\''),
  const Consejo(category: 'Duelo', title: 'Consuelo en el Duelo', description: 'En el proceso del duelo, busca el consuelo que solo Dios puede dar. Él es cercano a los quebrantados de corazón. Permite que Él te sane y te dé paz.', verse: 'Salmo 34:18: \'Cercano está Jehová a los quebrantados de corazón; Y salva a los contritos de espíritu.\''),
  const Consejo(category: 'Amargura', title: 'Despojándote de la Amargura', description: 'La amargura es una carga pesada. Despójate de ella, perdona a quienes te ofendieron y permite que el Espíritu Santo llene tu corazón de amor y paz.', verse: 'Efesios 4:31: \'Quítense de vosotros toda amargura, enojo, ira, gritería y maledicencia, y toda malicia.\''),
  const Consejo(category: 'Inseguridad', title: 'Confiado en Cristo', description: 'No hay razón para la inseguridad cuando Cristo vive en ti. Él te ha dado toda autoridad y poder. Camina con confianza, sabiendo quién eres en Él.', verse: 'Filipenses 4:13: \'Todo lo puedo en Cristo que me fortalece.\''),
  const Consejo(category: 'Pereza', title: 'Diligencia en el Señor', description: 'Sé diligente en todo lo que hagas, como para el Señor. Tu esfuerzo no es en vano. Dios bendice el trabajo de tus manos si lo haces con un corazón dispuesto.', verse: 'Colosenses 3:23: \'Y todo lo que hagáis, hacedlo de corazón, como para el Señor y no para los hombres;\''),
  const Consejo(category: 'Chisme', title: 'Edificando con tus Palabras', description: 'Usa tus palabras para edificar, no para destruir. Evita el chisme y el juicio, y en su lugar, ofrece palabras de aliento, verdad y gracia a los demás.', verse: 'Efesios 4:29: \'Ninguna palabra corrompida salga de vuestra boca, sino la que sea buena para la necesaria edificación, a fin de dar gracia a los oyentes.\''),
  const Consejo(category: 'Crítica', title: 'Respondiendo a la Crítica con Gracia', description: 'Cuando enfrentes críticas, responde con gracia y humildad. Discierne si hay algo que aprender, y si no, entrégalo a Dios. Tu paz es más valiosa.', verse: 'Proverbios 15:1: \'La blanda respuesta quita la ira; Mas la palabra áspera hace subir el furor.\''),
  const Consejo(category: 'Abundancia', title: 'La Abundancia para Compartir', description: 'Cuando Dios te da en abundancia, es para que seas una bendición para otros. Sé generoso y comparte tus recursos con quienes tienen necesidad.', verse: '2 Corintios 9:8: \'Y poderoso es Dios para hacer que abunde en vosotros toda gracia, a fin de que, teniendo siempre en todas las cosas todo lo suficiente, abundéis para toda buena obra;\''),
  const Consejo(category: 'Pobreza', title: 'La Riqueza en Cristo', description: 'Aunque enfrentes pobreza material, recuerda que eres rico en Cristo. Tu verdadera riqueza está en tu relación con Él y en las promesas de Su Reino.', verse: '2 Corintios 8:9: \'Porque ya conocéis la gracia de nuestro Señor Jesucristo, que por amor a vosotros se hizo pobre, siendo rico, para que vosotros con su pobreza fueseis enriquecidos.\''),
  const Consejo(category: 'Salud', title: 'Dios es tu Sanador', description: 'En toda enfermedad, Dios es tu sanador. Confía en Él para tu restauración y busca Su voluntad en tu salud. Él tiene el poder para traer sanidad.', verse: 'Éxodo 15:26: \'Y dijo: Si oyeres atentamente la voz de Jehová tu Dios, e hicieres lo recto delante de sus ojos, y dieres oído a sus mandamientos, y guardares todos sus estatutos, ninguna enfermedad de las que envié a los egipcios te enviaré a ti; porque yo soy Jehová tu sanador.\''),
  const Consejo(category: 'Mente', title: 'Paz en tu Mente', description: 'La paz en tu mente es un regalo de Dios. Renueva tus pensamientos con Su Palabra, y Él te dará una mente tranquila y en reposo en Él.', verse: 'Isaías 26:3: \'Tú guardarás en completa paz a aquel cuyo pensamiento en ti persevera; porque en ti ha confiado.\''),
  const Consejo(category: 'Amor', title: 'El Amor Nunca Deja de Ser', description: 'El amor de Dios es eterno e inagotable. Refléjalo en tu vida a través de acciones de bondad, paciencia y servicio a los demás. El amor es el mayor don.', verse: '1 Corintios 13:8: \'El amor nunca deja de ser; pero las profecías se acabarán, y cesarán las lenguas, y la ciencia acabará.\''),
  const Consejo(category: 'Esperar en Dios', title: 'Esperar con Propósito', description: 'Esperar en Dios no es pasividad, es una espera activa con propósito. Confía en que Él está obrando, incluso en el silencio. Su tiempo es perfecto.', verse: 'Salmo 37:7: \'Guarda silencio ante Jehová, y espera en él; No te alteres con motivo del que prospera en su camino, Por el hombre que hace maldades.\''),
  const Consejo(category: 'Confianza', title: 'La Confianza Viene de Dios', description: 'Tu verdadera confianza no proviene de tus habilidades, sino de Dios en ti. Él te capacita y te da la fuerza para enfrentar cada desafío. Confía plenamente en Él.', verse: 'Filipenses 4:13: \'Todo lo puedo en Cristo que me fortalece.\''),
  const Consejo(category: 'Pasion', title: 'Pasión por el Reino de Dios', description: 'Que tu pasión sea por el reino de Dios y Su justicia. Vive cada día con un corazón ardiente por Él, buscando Su voluntad y sirviéndole con fervor.', verse: 'Romanos 12:11: \'En lo que requiere diligencia, no perezosos; fervientes en espíritu, sirviendo al Señor;\''),
  const Consejo(category: 'Disciplina', title: 'La Disciplina Te Perfecciona', description: 'La disciplina, aunque a veces dolorosa, te perfecciona. Somete tu vida a la disciplina de Dios, y te moldeará a la imagen de Cristo.', verse: 'Hebreos 12:10: \'Porque ellos ciertamente por pocos días nos disciplinaban a su manera; mas éste para lo que nos es provechoso, para que participemos de su santidad.\''),
  const Consejo(category: 'Compasion', title: 'Compasión Activa', description: 'La compasión no es solo sentir; es actuar. Sé las manos y los pies de Jesús, mostrando compasión activa a quienes sufren y necesitan ayuda.', verse: '1 Juan 3:17-18: \'Pero el que tiene bienes de este mundo y ve a su hermano tener necesidad, y cierra contra él su corazón, ¿cómo mora el amor de Dios en él? Hijitos míos, no amemos de palabra ni de lengua, sino de hecho y en verdad.\''),
  const Consejo(category: 'Arrepentimiento', title: 'Un Nuevo Comienzo a Través del Arrepentimiento', description: 'El arrepentimiento es la puerta a un nuevo comienzo. No importa cuán lejos te hayas alejado, Dios te espera con los brazos abiertos para perdonarte y restaurarte.', verse: 'Hechos 2:38: \'Pedro les dijo: Arrepentíos, y bautícese cada uno de vosotros en el nombre de Jesucristo para perdón de los pecados; y recibiréis el don del Espíritu Santo.\''),
  const Consejo(category: 'Dones', title: 'Dones para el Servicio', description: 'Tus dones espirituales no son para ti mismo, sino para el servicio del cuerpo de Cristo. Úsalos con diligencia y humildad para edificar a los demás.', verse: 'Romanos 12:6-8: \'De manera que, teniendo diferentes dones, según la gracia que nos es dada, si el de profecía, úsese conforme a la medida de la fe; o si de servicio, en servir; o el que enseña, en la enseñanza; el que exhorta, en la exhortación; el que reparte, con liberalidad; el que preside, con solicitud; el que hace misericordia, con alegría.\''),
  const Consejo(category: 'Gratitud', title: 'La Gratitud Transforma tu Actitud', description: 'La gratitud es una elección que transforma tu actitud. Enfócate en las bendiciones, no en las carencias, y verás cómo tu corazón se llena de gozo y paz.', verse: 'Colosenses 3:17: \'Y todo lo que hacéis, sea de palabra o de hecho, hacedlo todo en el nombre del Señor Jesús, dando gracias a Dios Padre por medio de él.\''),
  const Consejo(category: 'Humildad', title: 'Vestidos de Humildad', description: 'Revístete de humildad, porque Dios resiste a los soberbios y da gracia a los humildes. La humildad te abre puertas a la bendición y a la verdadera relación con Dios.', verse: '1 Pedro 5:5: \'Igualmente, jóvenes, estad sujetos a los ancianos; y todos, sumisos unos a otros, revestíos de humildad; porque: Dios resiste a los soberbios, y da gracia a los humildes.\''),
  const Consejo(category: 'Fidelidad', title: 'La Fidelidad a la Palabra de Dios', description: 'Sé fiel a la Palabra de Dios, estúdiala, medítala y vívela. Es tu guía segura en un mundo incierto. Su verdad te hará libre y te mantendrá firme.', verse: 'Salmo 119:105: \'Lámpara es a mis pies tu palabra, Y lumbrera a mi camino.\''),
  const Consejo(category: 'Esperanza Eterna', title: 'La Gloria que Nos Espera', description: 'Nuestra esperanza eterna en Cristo es la gloria que nos espera. Vive con los ojos puestos en la eternidad, y las aflicciones de este mundo parecerán ligeras y temporales.', verse: 'Romanos 8:18: \'Pues tengo por cierto que las aflicciones del tiempo presente no son comparables con la gloria venidera que en nosotros ha de manifestarse.\''),
  const Consejo(category: 'Sabiduria', title: 'La Sabiduría: Un Tesoro Invaluable', description: 'Busca la sabiduría de Dios como un tesoro invaluable. Te guiará en cada decisión, te protegerá del mal y te llevará por sendas de vida.', verse: 'Proverbios 4:7: \'Sabiduría ante todo; adquiere sabiduría; Y sobre todas tus posesiones adquiere inteligencia.\''),
  const Consejo(category: 'Amistad', title: 'Un Amigo en Cristo', description: 'Cuando te sientas solo, recuerda que tienes un amigo fiel en Cristo Jesús. Él te comprende, te acompaña y nunca te abandonará. Invítale a tu amistad.', verse: 'Juan 15:15: \'Ya no os llamaré siervos, porque el siervo no sabe lo que hace su señor; pero os he llamado amigos, porque todas las cosas que oí de mi Padre, os las he dado a conocer.\''),
  const Consejo(category: 'Ansiedad', title: 'Paz en la Ansiedad', description: 'Cuando la ansiedad te invada, dirige tus pensamientos a Cristo. Su paz es un don que guarda tu corazón y tu mente, incluso en la tormenta.', verse: 'Filipenses 4:7: \'Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.\''),
  const Consejo(category: 'PerdÃ³n', title: 'El Perdón es un Acto de Voluntad', description: 'El perdón no es esperar a sentirlo, es una decisión de la voluntad. Elige perdonar, y el sentimiento de liberación seguirá. Es un mandamiento de Dios.', verse: 'Efesios 4:32: \'Antes sed benignos unos con otros, misericordiosos, perdonándoos unos a otros, como Dios también os perdonó a vosotros en Cristo.\''),
  const Consejo(category: 'Fe', title: 'Fe en la Fidelidad de Dios', description: 'Tu fe no está en tus fuerzas, sino en la fidelidad de Dios. Él es digno de toda tu confianza. Aunque todo falle, Él permanecerá fiel a Sus promesas.', verse: '2 Timoteo 2:13: \'Si fuéremos infieles, él permanece fiel; Él no puede negarse a sí mismo.\''),
  const Consejo(category: 'Relaciones', title: 'Edificando Relaciones en Cristo', description: 'Construye tus relaciones sobre el fundamento de Cristo. Ámense, anímense y sirvanse mutuamente, reflejando el amor de Dios a un mundo que lo necesita.', verse: 'Romanos 15:7: \'Por tanto, recibíos los unos a los otros, como también Cristo nos recibió, para gloria de Dios.\''),
  const Consejo(category: 'Finanzas', title: 'Contentamiento y Confianza en las Finanzas', description: 'Aprende a estar contento con lo que tienes y a confiar en Dios para lo que no tienes. Él es tu fuente inagotable y tu proveedor fiel en todas tus necesidades financieras.', verse: 'Filipenses 4:19: \'Mi Dios, pues, suplirá todo lo que os falta conforme a sus riquezas en gloria en Cristo Jesús.\''),
  const Consejo(category: 'DepresiÃ³n', title: 'Dios te Rescata de la Depresión', description: 'Cuando la depresión te encierre, clama a Dios. Él es tu Libertador y te rescatará del abismo. Su mano poderosa está extendida para levantarte.', verse: 'Salmo 18:16: \'Envió desde lo alto; me tomó, Me sacó de las muchas aguas.\''),
  const Consejo(category: 'Paz', title: 'La Paz que no Entendemos', description: 'La paz de Dios no siempre tiene sentido lógico, pero es real. Guarda tu corazón y tu mente en Cristo Jesús, y Su paz te envolverá, incluso en la confusión.', verse: 'Filipenses 4:7: \'Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.\''),
  const Consejo(category: 'Tristeza', title: 'Transformando la Tristeza en Gozo', description: 'Dios puede transformar tu tristeza en gozo. Llora delante de Él, y confía en que Su presencia cambiará tu lamento en danza. Su fidelidad es grande.', verse: 'Salmo 30:11: \'Has cambiado mi lamento en baile; Desataste mi cilicio, y me ceñiste de alegría.\''),
  const Consejo(category: 'Paciencia', title: 'La Paciencia de un Corazón Fiel', description: 'Cultiva la paciencia en tu corazón, sabiendo que Dios está obrando en ti y a través de ti. No te apresures; confía en Su tiempo perfecto para todas las cosas.', verse: 'Lamentaciones 3:25: \'Bueno es Jehová a los que en él esperan, al alma que le busca.\''),
  const Consejo(category: 'Gozo', title: 'El Gozo es tu Medicina', description: 'El gozo del Señor es como una buena medicina para tu alma. Mantén tu gozo en Él, incluso en las dificultades, y verás cómo te fortalece y te sana.', verse: 'Proverbios 17:22: \'El corazón alegre constituye buen remedio; Mas el espíritu triste seca los huesos.\''),
  const Consejo(category: 'Mente', title: 'Una Mente Renovada', description: 'Renueva tu mente diariamente con la Palabra de Dios. Permite que Sus pensamientos se conviertan en los tuyos, y experimentarás una transformación en tu forma de vivir.', verse: 'Romanos 12:2: \'No os conforméis a este siglo, sino transformaos por medio de la renovación de vuestro entendimiento, para que comprobéis cuál sea la buena voluntad de Dios, agradable y perfecta.\''),
  const Consejo(category: 'Sabiduria', title: 'La Sabiduría para el Día a Día', description: 'Pide a Dios sabiduría para tus decisiones diarias, grandes o pequeñas. Él te guiará y te dará el discernimiento que necesitas para vivir sabiamente.', verse: 'Santiago 1:5: \'Y si alguno de vosotros tiene falta de sabiduría, pídala a Dios, el cual da a todos abundantemente y sin reproche, y le será dada.\''),
  const Consejo(category: 'Amor', title: 'El Amor de Cristo en Acción', description: 'Demuestra el amor de Cristo con acciones tangibles. Sé un agente de Su amor en tu comunidad y en tu mundo, reflejando Su corazón compasivo.', verse: '1 Juan 4:11: \'Amados, si Dios nos ha amado así, debemos también nosotros amarnos unos a otros.\''),
  const Consejo(category: 'Esperar en Dios', title: 'Esperar con Confianza', description: 'Espera en el Señor con confianza, porque Su fidelidad es inquebrantable. Él es digno de tu espera y te recompensará por tu paciencia.', verse: 'Salmo 40:1: \'Pacientemente esperé a Jehová, Y se inclinó a mí, y oyó mi clamor.\''),
  const Consejo(category: 'Confianza', title: 'Confianza en la Soberanía de Dios', description: 'Confía en la soberanía de Dios, sabiendo que Él tiene el control de todo. Nada escapa a Su conocimiento o a Su plan perfecto para tu vida.', verse: 'Romanos 8:28: \'Y sabemos que a los que aman a Dios, todas las cosas les ayudan a bien, esto es, a los que conforme a su propósito son llamados.\''),
  const Consejo(category: 'Pasion', title: 'Renueva tu Pasión por Su Propósito', description: 'Si tu pasión se ha desvanecido, pide a Dios que la renueve. Reaviva tu fuego por Su propósito en tu vida y sírvele con un corazón ardiente.', verse: 'Romanos 12:11: \'En lo que requiere diligencia, no perezosos; fervientes en espíritu, sirviendo al Señor;\''),
  const Consejo(category: 'Disciplina', title: 'La Disciplina: Un Sendero a la Libertad', description: 'La disciplina, aunque difícil, es un sendero hacia la verdadera libertad. Sométete a la corrección de Dios, y te guiará a la vida abundante en Cristo.', verse: 'Proverbios 13:18: \'Pobreza y vergüenza tendrá el que menosprecia el consejo; Mas el que guarda la corrección recibirá honra.\''),
  const Consejo(category: 'Compasion', title: 'Corazón de Compasión', description: 'Ten un corazón de compasión como el de Jesús. Muestra empatía y amor a quienes te rodean, especialmente a los que están sufriendo o en necesidad.', verse: 'Colosenses 3:12: \'Vestíos, pues, como escogidos de Dios, santos y amados, de entrañable misericordia, de benignidad, de humildad, de mansedumbre, de paciencia;\''),
  const Consejo(category: 'Arrepentimiento', title: 'El Fruto del Arrepentimiento', description: 'El verdadero arrepentimiento produce frutos dignos: un cambio de vida, restauración y una profunda relación con Dios. Camina en ese nuevo comienzo.', verse: 'Hechos 26:20: \'sino que anuncié primeramente a los que están en Damasco, y Jerusalén, y por toda la tierra de Judea, y a los gentiles, que se arrepintiesen y se convirtiesen a Dios, haciendo obras dignas de arrepentimiento.\''),
  const Consejo(category: 'Dones', title: 'Usando tus Dones para la Gloria de Dios', description: 'Tus dones espirituales son para la gloria de Dios. Úsalos diligentemente para edificar a la iglesia y extender Su reino en la tierra. Sé un buen mayordomo.', verse: '1 Corintios 12:7: \'Pero a cada uno le es dada la manifestación del Espíritu para provecho.\''),
  const Consejo(category: 'Gratitud', title: 'Un Estilo de Vida de Gratitud', description: 'Haz de la gratitud un estilo de vida. Agradece a Dios en todo, y verás cómo tu corazón se llena de gozo y tu perspectiva se eleva por encima de las circunstancias.', verse: '1 Tesalonicenses 5:18: \'Dad gracias en todo, porque esta es la voluntad de Dios para con vosotros en Cristo Jesús.\''),
  const Consejo(category: 'Humildad', title: 'La Humildad: Camino a la Grandeza', description: 'Si quieres ser grande en el reino de Dios, sé humilde. La humildad es el camino a la verdadera grandeza y al favor de Dios. Sirve a los demás con un corazón humilde.', verse: 'Mateo 23:12: \'Porque el que se enaltece será humillado, y el que se humilla será enaltecido.\''),
  const Consejo(category: 'Fidelidad', title: 'Dios es Fiel', description: 'En medio de la infidelidad del mundo, Dios permanece fiel. Puedes confiar plenamente en Su carácter y en Sus promesas. Él nunca te fallará.', verse: 'Salmo 89:8: \'Jehová Dios de los ejércitos, ¿Quién como tú? Poderoso eres, Jehová, Y tu fidelidad te rodea.\''),
  const Consejo(category: 'Esperanza Eterna', title: 'Nuestra Esperanza Bendita', description: 'Nuestra esperanza bendita es la venida de Cristo y la vida eterna con Él. Vive con esta perspectiva, y las dificultades de esta vida serán insignificantes.', verse: 'Tito 2:13: \'aguardando la esperanza bienaventurada y la manifestación gloriosa de nuestro gran Dios y Salvador Jesucristo,\''),
  const Consejo(category: 'Sabiduria', title: 'La Sabiduría de lo Alto', description: 'La sabiduría que viene de lo alto es pura, pacífica y llena de misericordia. Pídela a Dios, y Él te la dará generosamente para guiar tu vida.', verse: 'Santiago 3:17: \'Pero la sabiduría que es de lo alto es primeramente pura, después pacífica, amable, benigna, llena de misericordia y de buenos frutos, sin incertidumbre ni hipocresía.\''),
  const Consejo(category: 'Amistad', title: 'Amistades que Edifican', description: 'Cultiva amistades que te edifiquen en la fe, te animen en los tiempos difíciles y te ayuden a crecer en tu caminar con Cristo. Son un regalo precioso.', verse: 'Eclesiastés 4:9-10: \'Mejores son dos que uno; porque tienen mejor paga de su trabajo. Porque si cayeren, el uno levantará a su compañero; pero ¡ay del solo! que cuando cayere, no habrá segundo que lo levante.\''),
  const Consejo(category: 'Ansiedad', title: 'Respira la Paz de Dios', description: 'Cuando la ansiedad te quite el aliento, respira la paz de Dios. Él está contigo, controlando cada detalle. Su calma te inundará si le entregas tus cargas.', verse: 'Salmo 46:1: \'Dios es nuestro amparo y fortaleza, Nuestro pronto auxilio en las tribulaciones.\''),
  const Consejo(category: 'PerdÃ³n', title: 'El Perdón es un Acto de Gracia', description: 'Perdonar es un acto de gracia, un reflejo del perdón que has recibido de Cristo. Libera a otros, y libérate a ti mismo. Es el camino a la sanidad.', verse: 'Efesios 4:32: \'Antes sed benignos unos con otros, misericordiosos, perdonándoos unos a otros, como Dios también os perdonó a vosotros en Cristo.\''),
  const Consejo(category: 'Fe', title: 'La Fe es un Escudo', description: 'Tu fe es un escudo contra los ataques del enemigo. Mantente firme en la verdad de Dios y confía en Su protección. Con fe, ninguna arma forjada contra ti prosperará.', verse: 'Efesios 6:16: \'Sobre todo, tomad el escudo de la fe, con que podáis apagar todos los dardos de fuego del maligno;\''),
  const Consejo(category: 'Relaciones', title: 'El Amor en Práctica', description: 'El amor en las relaciones se demuestra en la práctica: en la paciencia, la bondad, el perdón y el servicio. Ama a los demás como Cristo te ama.', verse: '1 Corintios 13:4-7: \'El amor es sufrido, es benigno; el amor no tiene envidia, el amor no es jactancioso, no se envanece; no hace nada indebido, no busca lo suyo, no se irrita, no guarda rencor; no se goza de la injusticia, mas se goza de la verdad. Todo lo sufre, todo lo cree, todo lo espera, todo lo soporta.\''),
  const Consejo(category: 'Finanzas', title: 'Mayordomía Fiel', description: 'Sé un mayordomo fiel de los recursos que Dios te ha confiado. Administra tus finanzas con sabiduría, prudencia y generosidad, para Su gloria.', verse: '1 Pedro 4:10: \'Cada uno según el don que ha recibido, minístrelo a los otros, como buenos administradores de la multiforme gracia de Dios.\''),
  const Consejo(category: 'DepresiÃ³n', title: 'Un Canto en la Noche', description: 'Incluso en la noche de la depresión, Dios puede poner un canto en tu corazón. Búscalo en la oscuridad, y Él te dará un motivo para alabarle.', verse: 'Salmo 42:8: \'Pero de día mandará Jehová su misericordia, Y de noche su cántico estará conmigo, Y mi oración al Dios de mi vida.\''),
  const Consejo(category: 'Miedo', title: 'El Miedo es una Ilusión', description: 'A menudo, el miedo es una ilusión que te impide avanzar. Deséchalo, confiando en el Dios que es más grande que cualquier gigante que enfrentes.', verse: 'Salmo 23:4: \'Aunque ande en valle de sombra de muerte, No temeré mal alguno, porque tú estarás conmigo; Tu vara y tu cayado me infundirán aliento.\''),
  const Consejo(category: 'Paz Interior', title: 'Tu Ancla de Paz', description: 'En el mar agitado de la vida, Cristo es tu ancla de paz. Permanece en Él, y Él te dará la calma en tu interior, sin importar las olas que te rodeen.', verse: 'Juan 14:27: \'La paz os dejo, mi paz os doy; yo no os la doy como el mundo la da. No se turbe vuestro corazón, ni tenga miedo.\''),
  const Consejo(category: 'Tristeza', title: 'Dios te Recoge en tu Tristeza', description: 'Cuando la tristeza te abrume, Dios te recoge. Él está cerca de los quebrantados de corazón. Permite que Su amor te consuele y te dé esperanza.', verse: 'Salmo 34:18: \'Cercano está Jehová a los quebrantados de corazón; Y salva a los contritos de espíritu.\''),
  const Consejo(category: 'Generosidad', title: 'La Mano Abierta de Dios', description: 'Sé de mano abierta, porque Dios es de mano abierta contigo. Tu generosidad no solo bendice a otros, sino que también abre las puertas para que Dios te bendiga más.', verse: 'Proverbios 11:24-25: \'Hay quienes reparten, y les es añadido más; Y hay quienes retienen más de lo que es justo, y vienen a pobreza. El alma generosa será prosperada; Y el que saciare, él también será saciado.\''),
  const Consejo(category: 'Humildad', title: 'La Belleza de la Humildad', description: 'La verdadera belleza no es externa, sino la de un espíritu humilde y manso. Vístete de humildad, y Dios te honrará y te usará poderosamente.', verse: '1 Pedro 3:3-4: \'Vuestro atavío no sea el externo de peinados ostentosos, de adornos de oro o de vestidos lujosos, sino el interno, el del corazón, en el incorruptible ornato de un espíritu afable y apacible, que es de grande estima delante de Dios.\''),
  const Consejo(category: 'Fidelidad', title: 'Fidelidad hasta el Fin', description: 'Sé fiel a Dios hasta el fin de tus días. Él es tu recompensa. Tu fidelidad a Él en esta vida te asegurará una eternidad de gozo en Su presencia.', verse: 'Apocalipsis 2:10: \'No temas en nada lo que vas a padecer. He aquí, el diablo echará a algunos de vosotros en la cárcel, para que seáis probados, y tendréis tribulación por diez días. Sé fiel hasta la muerte, y yo te daré la corona de la vida.\''),
  const Consejo(category: 'Esperanza Eterna', title: 'Un Futuro Glorioso', description: 'Tu futuro es glorioso en Cristo. Aunque las pruebas de esta vida sean difíciles, tu esperanza eterna en Él te da la fuerza para perseverar y el gozo para celebrar.', verse: 'Filipenses 3:20-21: \'Mas nuestra ciudadanía está en los cielos, de donde también esperamos al Salvador, al Señor Jesucristo; el cual transformará el cuerpo de la humillación nuestra, para que sea semejante al cuerpo de la gloria suya, por el poder con el cual puede también sujetar a sí mismo todas las cosas.\''),
  const Consejo(category: 'Sabiduria', title: 'Sabiduría Práctica para la Vida', description: 'La sabiduría de Dios no es solo teoría; es práctica para tu vida diaria. Búscala en Su Palabra, y te dará dirección para cada decisión y cada paso.', verse: 'Proverbios 2:6: \'Porque Jehová da la sabiduría, Y de su boca viene el conocimiento y la inteligencia.\''),
  const Consejo(category: 'Amistad', title: 'Amigos en Todas las Estaciones', description: 'Los verdaderos amigos permanecen en todas las estaciones de la vida. Valora a quienes te aman, te apoyan y te desafían a crecer en Cristo. Son un tesoro.', verse: 'Proverbios 18:24: \'El hombre que tiene amigos debe mostrarse amigo; Y amigo hay más unido que un hermano.\''),
  const Consejo(category: 'Ansiedad', title: 'Paz: Antídoto para la Ansiedad', description: 'La paz de Dios es el antídoto perfecto para la ansiedad. En lugar de preocuparte, ora, confía y deja que Su paz inunde tu corazón y mente.', verse: 'Filipenses 4:6-7: \'Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias. Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.\''),
  const Consejo(category: 'PerdÃ³n', title: 'El Perdón es un Acto de Amor', description: 'Perdonar es un acto de amor, tanto hacia los demás como hacia ti mismo. Te libera de la carga del rencor y te permite caminar en la libertad de Cristo.', verse: 'Colosenses 3:13: \'soportándoos unos a otros, y perdonándoos unos a otros si alguno tuviere queja contra otro. De la manera que Cristo os perdonó, así también hacedlo vosotros.\''),
  const Consejo(category: 'Fe', title: 'La Fe es la Perspectiva de Dios', description: 'La fe te permite ver las cosas desde la perspectiva de Dios. Confía en Su plan, aunque no lo entiendas. Él obra todas las cosas para tu bien y Su gloria.', verse: 'Romanos 8:28: \'Y sabemos que a los que aman a Dios, todas las cosas les ayudan a bien, esto es, a los que conforme a su propósito son llamados.\''),
  const Consejo(category: 'Relaciones', title: 'Construyendo Puentes en las Relaciones', description: 'En lugar de construir muros, construye puentes en tus relaciones. Busca la reconciliación, el entendimiento y el amor, y sé un pacificador en Cristo.', verse: 'Romanos 12:18: \'Si es posible, en cuanto dependa de vosotros, tened paz con todos los hombres.\''),
  const Consejo(category: 'Finanzas', title: 'La Libertad Financiera', description: 'La verdadera libertad financiera no está en la acumulación, sino en la mayordomía fiel. Administra tus recursos con sabiduría y en obediencia a Dios, y Él te proveerá.', verse: 'Proverbios 3:9-10: \'Honra a Jehová con tus bienes, Y con las primicias de todos tus frutos; Y serán llenos tus graneros con abundancia, Y tus lagares rebosarán de mosto.\''),
  const Consejo(category: 'DepresiÃ³n', title: 'La Presencia de Dios en la Depresión', description: 'No estás solo en tu lucha contra la depresión. La presencia de Dios te rodea y te sostiene. Clama a Él y permite que Su amor te envuelva y te dé consuelo.', verse: 'Salmo 139:7-8: \'¿A dónde me iré de tu Espíritu? ¿Y a dónde huiré de tu presencia? Si subiere a los cielos, allí estás tú; Y si en el Seol hiciere mi estrado, he aquí, allí tú estás.\''),
  const Consejo(category: 'Miedo', title: 'Miedo vs. Fe', description: 'El miedo es lo opuesto a la fe. Cuando el miedo te amenace, elige la fe. Confía en el poder de Dios y en Su promesa de estar contigo en todo momento.', verse: '2 Timoteo 1:7: \'Porque no nos ha dado Dios espíritu de cobardía, sino de poder, de amor y de dominio propio.\''),
  const Consejo(category: 'Paz Interior', title: 'Cultiva tu Jardín de Paz', description: 'Tu corazón es un jardín. Cultiva la paz plantando semillas de la Palabra de Dios y regándolas con oración. Cosecharás una paz que sobrepasa todo entendimiento.', verse: 'Filipenses 4:7: \'Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.\''),
  const Consejo(category: 'Tristeza', title: 'Dios en Tus Lágrimas', description: 'Dios recoge tus lágrimas en Su odre. Él ve tu tristeza y te consuela. No tengas miedo de llorar, porque Él está cerca de los que tienen el corazón quebrantado.', verse: 'Salmo 56:8: \'Mis andanzas tú has contado; Pon mis lágrimas en tu redoma; ¿No están ellas en tu libro?\''),
  const Consejo(category: 'Paciencia', title: 'La Paciencia es una Virtud', description: 'La paciencia es una virtud que te acercará a Dios. Espera en Su tiempo perfecto, y Él te fortalecerá y te mostrará Su plan en el momento adecuado.', verse: 'Salmo 27:14: \'Espera a Jehová; Esfuérzate, y aliéntese tu corazón; Sí, espera a Jehová.\''),
  const Consejo(category: 'Gozo', title: 'El Gozo del Señor', description: 'El gozo del Señor es tu fuerza. No busques gozo en las circunstancias, sino en Él. Su presencia es la fuente de una alegría inquebrantable que te sostiene.', verse: 'Nehemías 8:10: \'Luego les dijo: Id, comed grosuras, y bebed vino dulce, y enviad porciones a los que no tienen nada preparado; porque este día es santo a nuestro Señor; no os entristezcáis, porque el gozo de Jehová es vuestra fuerza.\''),
  const Consejo(category: 'Mente', title: 'Protege tu Mente', description: 'Protege tu mente de los pensamientos negativos y destructivos. Llénala con la verdad de la Palabra de Dios y Su Espíritu Santo te dará paz.', verse: '2 Corintios 10:5: \'derribando argumentos y toda altivez que se levanta contra el conocimiento de Dios, y llevando cautivo todo pensamiento a la obediencia a Cristo,\''),
  const Consejo(category: 'Sabiduria', title: 'Sabiduría: Más Preciosa que el Oro', description: 'La sabiduría de Dios es un tesoro más precioso que el oro. Búscala con diligencia, y te guiará por sendas de vida y te dará discernimiento en cada situación.', verse: 'Proverbios 8:11: \'Porque mejor es la sabiduría que las piedras preciosas; Y todo cuanto se puede desear, no se puede comparar a ella.\''),
  const Consejo(category: 'Amor', title: 'El Amor Permanece', description: 'En un mundo cambiante, el amor de Dios permanece. Refleja Su amor a los demás, porque el amor es el vínculo perfecto que une todas las cosas.', verse: '1 Corintios 13:13: \'Y ahora permanecen la fe, la esperanza y el amor, estos tres; pero el mayor de ellos es el amor.\''),
  const Consejo(category: 'Esperar en Dios', title: 'Esperar en la Soberanía de Dios', description: 'Espera en la soberanía de Dios, sabiendo que Él está obrando en todas las cosas para tu bien. Su plan es perfecto, aunque no lo entiendas completamente.', verse: 'Salmo 33:20: \'Nuestra alma espera a Jehová; Nuestra ayuda y nuestro escudo es él.\''),
  const Consejo(category: 'Confianza', title: 'La Confianza Viene del Conocimiento', description: 'Tu confianza en Dios crece a medida que le conoces más a través de Su Palabra. Dedica tiempo a estudiarla, y tu fe se fortalecerá.', verse: 'Romanos 10:17: \'Así que la fe es por el oír, y el oír, por la palabra de Dios.\''),
  const Consejo(category: 'Pasion', title: 'Reaviva el Fuego de tu Pasión', description: 'Si la rutina ha apagado tu pasión, reaviva el fuego. Vuelve a tu primer amor por Cristo y por Su propósito en tu vida. Sírvele con un corazón ardiente.', verse: 'Apocalipsis 2:4-5: \'Pero tengo contra ti, que has dejado tu primer amor. Recuerda por tanto de dónde has caído, y arrepiéntete, y haz las primeras obras; pues si no, vendré pronto a ti, y quitaré tu candelero de su lugar, si no te hubieres arrepentido.\''),
  const Consejo(category: 'Disciplina', title: 'La Disciplina: Un Acto de Amor', description: 'La disciplina de Dios es un acto de Su amor, no de Su ira. Acéptala con humildad, y te moldeará para ser más como Cristo. Es para tu bien.', verse: 'Hebreos 12:6: \'Porque el Señor al que ama, disciplina, y azota a todo el que recibe por hijo.\''),
  const Consejo(category: 'Compasion', title: 'Compasión para los Desfavorecidos', description: 'Extiende tu compasión a los desfavorecidos, a los pobres, a los marginados. Sigue el ejemplo de Jesús y sé una voz para los sin voz, un agente de esperanza.', verse: 'Proverbios 14:31: \'El que oprime al pobre afrenta a su Hacedor; Mas el que tiene misericordia del pobre, lo honra.\''),
  const Consejo(category: 'Arrepentimiento', title: 'Arrepentimiento Genuino', description: 'El arrepentimiento genuino es un regalo de Dios que te lleva a un cambio de vida. No temas volverte a Él, porque Su misericordia es nueva cada mañana.', verse: 'Lamentaciones 3:22-23: \'Por la misericordia de Jehová no hemos sido consumidos, porque nunca decayeron sus misericordias. Nuevas son cada mañana; grande es tu fidelidad.\''),
  const Consejo(category: 'Dones', title: 'Sirviendo con Tus Dones', description: 'No entierres tus dones; úsalos para servir a los demás y edificar el cuerpo de Cristo. Cada don es valioso en el plan de Dios.', verse: 'Mateo 25:14-30 (Parábola de los Talentos - concepto)'),
  const Consejo(category: 'Gratitud', title: 'El Secreto de la Alegría', description: 'El secreto de la verdadera alegría está en la gratitud. Cuando agradeces a Dios en todo, tu corazón se llena de un gozo que las circunstancias no pueden robar.', verse: 'Salmo 118:24: \'Este es el día que hizo Jehová; Nos gozaremos y alegraremos en él.\''),
  const Consejo(category: 'Humildad', title: 'La Humildad Atrae la Gracia', description: 'La humildad atrae la gracia de Dios. Cuando te humillas, Él te exalta. Busca la humildad en tu corazón y en tus acciones.', verse: 'Santiago 4:6: \'Pero él da mayor gracia. Por esto dice: Dios resiste a los soberbios, y da gracia a los humildes.\''),
  const Consejo(category: 'Fidelidad', title: 'Fidelidad en los Tiempos de Prueba', description: 'Tu fidelidad a Dios se prueba en los tiempos difíciles. Permanece firme, y Él te recompensará por tu perseverancia. Su fidelidad es tu ejemplo.', verse: '1 Pedro 1:6-7: \'En lo cual vosotros os alegráis, aunque ahora por un poco de tiempo, si es necesario, tengáis que ser afligidos en diversas pruebas, para que sometida a prueba vuestra fe, mucho más preciosa que el oro, el cual aunque perecedero se prueba con fuego, sea hallada en alabanza, gloria y honra cuando sea manifestado Jesucristo,\''),
  const Consejo(category: 'Esperanza Eterna', title: 'Anclados en la Esperanza Eterna', description: 'Permanece anclado en la esperanza eterna de Cristo. Esta es la verdad que te sostiene y te impulsa a vivir con propósito en este mundo.', verse: 'Hebreos 6:19: \'La cual tenemos como segura y firme ancla del alma, y que penetra hasta dentro del velo,\''),
  const Consejo(category: 'Sabiduria', title: 'La Sabiduría para Discipular', description: 'Pide a Dios sabiduría para discipular a otros y compartir con ellos las verdades de Su Palabra. Sé un mentor piadoso que guía a otros en su fe.', verse: 'Mateo 28:19-20: \'Por tanto, id, y haced discípulos a todas las naciones, bautizándolos en el nombre del Padre, y del Hijo, y del Espíritu Santo; enseñándoles que guarden todas las cosas que os he mandado; y he aquí yo estoy con vosotros todos los días, hasta el fin del mundo. Amén.\''),
  const Consejo(category: 'Amistad', title: 'La Amistad Verdadera', description: 'La amistad verdadera es un reflejo del amor de Cristo. Sé un amigo leal, que perdona, apoya y anima en todo momento.', verse: 'Proverbios 17:17: \'En todo tiempo ama el amigo, Y es como un hermano en tiempo de angustia.\''),
  const Consejo(category: 'Perdón', title: 'La misericordia de Dios sigue disponible', description: 'No importa cuántas veces hayas fallado, Dios sigue dispuesto a perdonar a quien se acerca con arrepentimiento sincero.', verse: '1 Juan 1:9: \'Si confesamos nuestros pecados, él es fiel y justo para perdonar nuestros pecados, y limpiarnos de toda maldad.\''),
  const Consejo(category: 'Perdón', title: 'Dios no desprecia un corazón arrepentido', description: 'El arrepentimiento genuino acerca el corazón nuevamente a Dios y abre paso a la restauración.', verse: 'Salmos 51:17: \'Al corazón contrito y humillado no despreciarás tú, oh Dios.\''),
  const Consejo(category: 'Perdón', title: 'La gracia es más grande que tu culpa', description: 'La gracia de Dios tiene poder para cubrir el pecado y traer nueva vida.', verse: 'Romanos 5:20: \'Mas cuando el pecado abundó, sobreabundó la gracia.\''),
  const Consejo(category: 'Perdón', title: 'Cristo vino a salvar, no a condenar', description: 'Jesús vino para rescatar al perdido y ofrecer reconciliación con Dios.', verse: 'Juan 3:17: \'Porque no envió Dios a su Hijo al mundo para condenar al mundo, sino para que el mundo sea salvo por él.\''),
  const Consejo(category: 'Perdón', title: 'Dios puede darte un nuevo comienzo', description: 'En Cristo siempre existe oportunidad de empezar de nuevo y caminar diferente.', verse: '2 Corintios 5:17: \'De modo que si alguno está en Cristo, nueva criatura es; las cosas viejas pasaron; he aquí todas son hechas nuevas.\''),
  const Consejo(category: 'Perdón', title: 'Su amor permanece aun después de fallar', description: 'El amor de Dios no desaparece cuando tropiezas; Él sigue llamándote a volver.', verse: 'Romanos 8:38-39: \'Ni la muerte, ni la vida... nos podrá separar del amor de Dios, que es en Cristo Jesús Señor nuestro.\''),
  const Consejo(category: 'Perdón', title: 'Dios borra tus transgresiones', description: 'El perdón de Dios es completo y verdadero para quien confía en Él.', verse: 'Isaías 43:25: \'Yo, yo soy el que borro tus rebeliones por amor de mí mismo, y no me acordaré de tus pecados.\''),
  const Consejo(category: 'Perdón', title: 'Puedes acercarte nuevamente a Dios', description: 'Jesús abrió el camino para volver a acercarnos al Padre con confianza.', verse: 'Hebreos 4:16: \'Acerquémonos, pues, confiadamente al trono de la gracia, para alcanzar misericordia.\''),
  const Consejo(category: 'Perdón', title: 'Dios es paciente contigo', description: 'La paciencia de Dios demuestra su deseo de restaurar y salvar.', verse: '2 Pedro 3:9: \'El Señor... es paciente para con nosotros, no queriendo que ninguno perezca, sino que todos procedan al arrepentimiento.\''),
  const Consejo(category: 'Perdón', title: 'Jesús entiende tu lucha', description: 'Cristo conoce el sufrimiento humano y puede ayudarte en medio de la debilidad.', verse: 'Hebreos 4:15: \'Porque no tenemos un sumo sacerdote que no pueda compadecerse de nuestras debilidades.\''),
  const Consejo(category: 'Perdón', title: 'El arrepentimiento trae vida', description: 'Volver a Dios produce transformación y restaura el corazón.', verse: 'Hechos 3:19: \'Así que, arrepentíos y convertíos, para que sean borrados vuestros pecados.\''),
  const Consejo(category: 'Perdón', title: 'Dios recibe al que vuelve', description: 'Como el padre del hijo pródigo, Dios recibe con amor a quien decide regresar.', verse: 'Lucas 15:20: \'Y cuando aún estaba lejos, lo vio su padre, y fue movido a misericordia.\''),
  const Consejo(category: 'Perdón', title: 'La misericordia de Dios es nueva cada día', description: 'Cada día es una nueva oportunidad para caminar cerca de Dios.', verse: 'Lamentaciones 3:22-23: \'Por la misericordia de Jehová no hemos sido consumidos... nuevas son cada mañana.\''),
  const Consejo(category: 'Perdón', title: 'No cargues eternamente la culpa', description: 'Dios desea liberar tu corazón de la culpa cuando vienes a Él sinceramente.', verse: 'Salmos 32:5: \'Mi pecado te declaré... y tú perdonaste la maldad de mi pecado.\''),
  const Consejo(category: 'Perdón', title: 'En Cristo hay redención', description: 'Jesús pagó el precio para que podamos recibir perdón y reconciliación.', verse: 'Efesios 1:7: \'En quien tenemos redención por su sangre, el perdón de pecados según las riquezas de su gracia.\''),
  const Consejo(category: 'Perdón', title: 'Perdona como Dios te perdonó', description: 'Recordar la gracia que recibiste ayuda a extender gracia a los demás.', verse: 'Efesios 4:32: \'Antes sed benignos unos con otros, misericordiosos, perdonándoos unos a otros, como Dios también os perdonó a vosotros en Cristo.\''),
  const Consejo(category: 'Perdón', title: 'El perdón trae libertad al corazón', description: 'Guardar rencor lastima el corazón; perdonar permite sanar y avanzar.', verse: 'Colosenses 3:13: \'Soportándoos unos a otros, y perdonándoos unos a otros si alguno tuviere queja contra otro. De la manera que Cristo os perdonó, así también hacedlo vosotros.\''),
  const Consejo(category: 'Perdón', title: 'Ama incluso cuando duele', description: 'El amor verdadero también se demuestra al decidir perdonar.', verse: '1 Pedro 4:8: \'Y ante todo, tened entre vosotros ferviente amor; porque el amor cubrirá multitud de pecados.\''),
  const Consejo(category: 'Perdón', title: 'No permitas que el odio crezca', description: 'El enojo prolongado puede endurecer el corazón si no se entrega a Dios.', verse: 'Efesios 4:26-27: \'Airaos, pero no pequéis; no se ponga el sol sobre vuestro enojo, ni deis lugar al diablo.\''),
  const Consejo(category: 'Perdón', title: 'Perdonar refleja el corazón de Cristo', description: 'Jesús mostró misericordia incluso hacia quienes le hicieron daño.', verse: 'Lucas 23:34: \'Padre, perdónalos, porque no saben lo que hacen.\''),
  const Consejo(category: 'Perdón', title: 'La misericordia vale más que el orgullo', description: 'A veces perdonar requiere humildad, pero trae paz al alma.', verse: 'Proverbios 19:11: \'La cordura del hombre detiene su furor, y su honra es pasar por alto la ofensa.\''),
  const Consejo(category: 'Perdón', title: 'Dios también trata contigo con paciencia', description: 'Así como Dios ha sido paciente contigo, puedes aprender a ser paciente con otros.', verse: 'Mateo 6:14: \'Porque si perdonáis a los hombres sus ofensas, os perdonará también a vosotros vuestro Padre celestial.\''),
  const Consejo(category: 'Perdón', title: 'No devuelvas mal por mal', description: 'Responder con bondad rompe ciclos de odio y resentimiento.', verse: 'Romanos 12:17: \'No paguéis a nadie mal por mal; procurad lo bueno delante de todos los hombres.\''),
  const Consejo(category: 'Perdón', title: 'La paz comienza en el corazón', description: 'Perdonar no cambia el pasado, pero puede cambiar lo que domina tu corazón hoy.', verse: 'Romanos 12:18: \'Si es posible, en cuanto dependa de vosotros, estad en paz con todos los hombres.\''),
  const Consejo(category: 'Perdón', title: 'El amor sabe perdonar', description: 'El amor verdadero no vive alimentando resentimientos constantemente.', verse: '1 Corintios 13:5: \'El amor... no guarda rencor.\''),
  const Consejo(category: 'Perdón', title: 'Perdonar también es obedecer a Dios', description: 'Aunque sea difícil, Dios llama a sus hijos a vivir en misericordia.', verse: 'Marcos 11:25: \'Y cuando estéis orando, perdonad, si tenéis algo contra alguno.\''),
  const Consejo(category: 'Perdón', title: 'La ira no debe gobernarte', description: 'Entregar el enojo a Dios evita que el resentimiento controle tu vida.', verse: 'Santiago 1:19-20: \'Todo hombre sea pronto para oír, tardo para hablar, tardo para airarse; porque la ira del hombre no obra la justicia de Dios.\''),
  const Consejo(category: 'Perdón', title: 'Dios sana corazones heridos', description: 'El perdón puede ser un proceso, pero Dios puede ayudarte a sanar.', verse: 'Salmos 147:3: \'Él sana a los quebrantados de corazón, y venda sus heridas.\''),
  const Consejo(category: 'Perdón', title: 'La bondad transforma más que el rencor', description: 'Responder con misericordia puede traer más cambio que responder con dureza.', verse: 'Romanos 12:21: \'No seas vencido de lo malo, sino vence con el bien el mal.\''),
  const Consejo(category: 'Perdón', title: 'El perdón abre camino a la restauración', description: 'Perdonar no siempre restaura relaciones, pero sí libera el corazón para sanar.', verse: 'Hebreos 12:14-15: \'Seguid la paz con todos... mirando bien, no sea que alguno deje de alcanzar la gracia de Dios; que brotando alguna raíz de amargura, os estorbe.\'')
];
